export const TEMPLATE_SOURCE: Record<string, TemplateFile[]> = {
  "analytics-dashboard": [{"file":"index.tsx","source":"'use client';\n// Analytics dashboard: \"Marlowe Tea\", a small store's admin.\n// Three views (Overview, Orders, Customers) in one file, sample data in ./data.ts,\n// charts in ./charts.tsx. The layout responds to the width of its container, not the\n// viewport, so it also works inside a panel, a split view or a preview frame.\nimport * as React from 'react';\nimport { Box, ButtonBase, DialogActions, DialogContent, DialogTitle, Divider, IconButton, Stack, Typography } from '@mui/material';\nimport SpaceDashboardOutlined from '@mui/icons-material/SpaceDashboardOutlined';\nimport ReceiptLongOutlined from '@mui/icons-material/ReceiptLongOutlined';\nimport PeopleAltOutlined from '@mui/icons-material/PeopleAltOutlined';\nimport MenuIcon from '@mui/icons-material/Menu';\nimport Close from '@mui/icons-material/Close';\nimport Add from '@mui/icons-material/Add';\nimport Search from '@mui/icons-material/Search';\nimport TrendingUp from '@mui/icons-material/TrendingUp';\nimport TrendingDown from '@mui/icons-material/TrendingDown';\nimport FileDownloadOutlined from '@mui/icons-material/FileDownloadOutlined';\nimport NotificationsNoneOutlined from '@mui/icons-material/NotificationsNoneOutlined';\nimport SearchOff from '@mui/icons-material/SearchOff';\nimport { Avatar, Badge, Button, Card, Chip, Dialog, Drawer, Pagination, Skeleton, Snackbar, Table, Tabs, TextField } from '@sorbet-ui/react';\nimport { colorPalette } from '@sorbet-ui/tokens';\nimport { AreaChart, BarList, Sparkline } from './charts';\nimport { ACTIVITY, CUSTOMERS, ORDERS, RANGES, STATUS_COLOR, TODAY, dayLabel, emailFor, initials, money, money2, summarize, type Accent, type Customer, type Order, type OrderStatus, type RangeId } from './data';\n\n// Container breakpoints: the root is the query container.\nconst CQ = { sm: '@container (min-width: 600px)', md: '@container (min-width: 900px)', lg: '@container (min-width: 1160px)' } as const;\n// Finger-sized targets on touch screens.\nconst TAP = { '@media (pointer: coarse)': { minHeight: 44, minWidth: 44 } } as const;\n\ntype View = 'overview' | 'orders' | 'customers';\nconst NAV: { id: View; label: string; icon: React.ReactNode }[] = [\n  { id: 'overview', label: 'Overview', icon: <SpaceDashboardOutlined fontSize=\"small\" /> },\n  { id: 'orders', label: 'Orders', icon: <ReceiptLongOutlined fontSize=\"small\" /> },\n  { id: 'customers', label: 'Customers', icon: <PeopleAltOutlined fontSize=\"small\" /> },\n];\n\n/** True while the element is narrower than `below` pixels. Used to drop table columns. */\nfunction useNarrow(ref: React.RefObject<HTMLElement | null>, below: number) {\n  const [narrow, setNarrow] = React.useState(false);\n  React.useEffect(() => {\n    const el = ref.current;\n    if (!el) return;\n    const ro = new ResizeObserver(([entry]) => setNarrow(entry.contentRect.width < below));\n    ro.observe(el);\n    return () => ro.disconnect();\n  }, [ref, below]);\n  return narrow;\n}\n\nfunction Panel({ title, action, children, sx }: { title: string; action?: React.ReactNode; children: React.ReactNode; sx?: object }) {\n  return (\n    <Card variant=\"outlined\" sx={{ p: 2.5, minWidth: 0, ...sx }}>\n      <Stack direction=\"row\" spacing={1} sx={{ alignItems: 'center', justifyContent: 'space-between', mb: 2, minHeight: 32 }}>\n        <Typography component=\"h3\" sx={{ fontWeight: 700, fontSize: 15 }}>\n          {title}\n        </Typography>\n        {action}\n      </Stack>\n      {children}\n    </Card>\n  );\n}\n\nconst StatusChip = ({ status }: { status: OrderStatus }) => <Chip size=\"sm\" variant=\"soft\" color={STATUS_COLOR[status]} label={status} />;\n\nfunction Empty({ title, body, action }: { title: string; body: string; action?: React.ReactNode }) {\n  return (\n    <Stack spacing={1} sx={{ alignItems: 'center', textAlign: 'center', py: 3 }}>\n      <SearchOff sx={{ fontSize: 32, color: 'text.secondary' }} />\n      <Typography sx={{ fontWeight: 700 }}>{title}</Typography>\n      <Typography variant=\"body2\" color=\"text.secondary\">\n        {body}\n      </Typography>\n      {action}\n    </Stack>\n  );\n}\n\nfunction ViewHeader({ title, sub, headingRef, action }: { title: string; sub: React.ReactNode; headingRef: React.Ref<HTMLHeadingElement>; action?: React.ReactNode }) {\n  return (\n    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, [CQ.sm]: { flexDirection: 'row', alignItems: 'flex-end', justifyContent: 'space-between' } }}>\n      <Box sx={{ minWidth: 0 }}>\n        <Typography ref={headingRef} component=\"h2\" tabIndex={-1} sx={{ fontWeight: 800, fontSize: 24, letterSpacing: '-0.02em', outline: 'none' }}>\n          {title}\n        </Typography>\n        <Typography variant=\"body2\" color=\"text.secondary\" sx={{ mt: 0.25 }}>\n          {sub}\n        </Typography>\n      </Box>\n      {action && <Box sx={{ flexShrink: 0, maxWidth: '100%' }}>{action}</Box>}\n    </Box>\n  );\n}\n\nconst PAGE_SIZE = 8;\ntype SortKey = 'id' | 'customer' | 'date' | 'status' | 'total';\n\nexport default function AnalyticsDashboard({ accent = 'primary' }: { accent?: Accent }) {\n  const root = React.useRef<HTMLDivElement>(null);\n  const heading = React.useRef<HTMLHeadingElement>(null);\n  const narrow = useNarrow(root, 720);\n\n  const [view, setView] = React.useState<View>('overview');\n  const [navOpen, setNavOpen] = React.useState(false);\n  const focusHeadingOnClose = React.useRef(false);\n\n  // Overview\n  const [range, setRange] = React.useState<RangeId>('30d');\n  const [loading, setLoading] = React.useState(false);\n  const loadTimer = React.useRef<number | undefined>(undefined);\n  React.useEffect(() => () => window.clearTimeout(loadTimer.current), []);\n  const stats = React.useMemo(() => summarize(range), [range]);\n  const changeRange = (next: RangeId) => {\n    if (next === range) return;\n    setRange(next);\n    // Stand-in for a request: show the loading state briefly.\n    setLoading(true);\n    window.clearTimeout(loadTimer.current);\n    loadTimer.current = window.setTimeout(() => setLoading(false), 450);\n  };\n\n  // Orders\n  const [orders, setOrders] = React.useState<Order[]>(ORDERS);\n  const [query, setQuery] = React.useState('');\n  const [status, setStatus] = React.useState<OrderStatus | 'All'>('All');\n  const [sort, setSort] = React.useState<{ by: SortKey; dir: 'asc' | 'desc' }>({ by: 'date', dir: 'desc' });\n  const [page, setPage] = React.useState(1);\n  const needle = query.trim().toLowerCase();\n  const filtered = React.useMemo(() => {\n    const rows = orders.filter((o) => (status === 'All' || o.status === status) && `${o.id} ${o.customer} ${o.email} ${o.channel}`.toLowerCase().includes(needle));\n    const value = (o: Order) => (sort.by === 'date' ? o.date * 10000 + Number(o.id.slice(3)) : sort.by === 'id' ? Number(o.id.slice(3)) : o[sort.by]);\n    return [...rows].sort((a, b) => {\n      const [x, y] = [value(a), value(b)];\n      const d = typeof x === 'number' && typeof y === 'number' ? x - y : String(x).localeCompare(String(y));\n      return sort.dir === 'asc' ? d : -d;\n    });\n  }, [orders, status, needle, sort]);\n  const pages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));\n  const current = Math.min(page, pages);\n  const pageRows = filtered.slice((current - 1) * PAGE_SIZE, current * PAGE_SIZE);\n  const pending = orders.filter((o) => o.status === 'Pending').length;\n\n  // Dialogs keep their content while they animate out: `open` flips first and the\n  // shown item is cleared when the exit transition ends.\n  const [orderOpen, setOrderOpen] = React.useState(false);\n  const [openOrder, setOpenOrder] = React.useState<Order | null>(null);\n  const returnFocus = React.useRef<HTMLElement | null>(null);\n  const showOrder = (o: Order) => {\n    returnFocus.current = document.activeElement instanceof HTMLElement ? document.activeElement : null;\n    setOpenOrder(o);\n    setOrderOpen(true);\n  };\n  const [newOpen, setNewOpen] = React.useState(false);\n  const [draft, setDraft] = React.useState({ customer: '', amount: '' });\n  const amountOk = Number(draft.amount) > 0;\n  const [customerOpen, setCustomerOpen] = React.useState(false);\n  const [customer, setCustomer] = React.useState<Customer | null>(null);\n  const [customerQuery, setCustomerQuery] = React.useState('');\n\n  // Each toast gets a new key, so a second message restarts the timer.\n  const [toast, setToast] = React.useState<{ id: number; message: string; open: boolean } | null>(null);\n  const notify = (message: string) => setToast((t) => ({ id: (t?.id ?? 0) + 1, message, open: true }));\n\n  const titleId = React.useId();\n  const newTitleId = React.useId();\n\n  const go = (next: View) => {\n    setView(next);\n    if (navOpen) {\n      focusHeadingOnClose.current = true;\n      setNavOpen(false);\n    }\n  };\n\n  const createOrder = () => {\n    const name = draft.customer.trim();\n    if (!name || !amountOk) return;\n    const total = Math.round(Number(draft.amount) * 100) / 100;\n    const next: Order = {\n      id: `MT-${Math.max(...orders.map((o) => Number(o.id.slice(3)))) + 1}`,\n      customer: name,\n      email: emailFor(name),\n      date: TODAY,\n      channel: 'Online store',\n      status: 'Pending',\n      lines: [{ name: 'Custom order', qty: 1, price: total }],\n      total,\n    };\n    setOrders((list) => [next, ...list]);\n    setPage(1);\n    setNewOpen(false);\n    notify(`Order ${next.id} created`);\n  };\n\n  const statsFor = (name: string) => {\n    const own = orders.filter((o) => o.customer === name);\n    return { count: own.length, spent: own.filter((o) => o.status === 'Paid' || o.status === 'Pending').reduce((a, o) => a + o.total, 0), own };\n  };\n\n  const nav = (\n    <Box component=\"nav\" aria-label=\"Dashboard\" sx={{ display: 'grid', gap: 0.5, p: 1.5 }}>\n      {NAV.map((n) => {\n        const on = view === n.id;\n        return (\n          <ButtonBase\n            key={n.id}\n            onClick={() => go(n.id)}\n            aria-current={on ? 'page' : undefined}\n            sx={{\n              justifyContent: 'flex-start',\n              gap: 1.5,\n              px: 1.5,\n              minHeight: 40,\n              borderRadius: '10px',\n              fontSize: 14,\n              fontWeight: on ? 700 : 500,\n              color: on ? 'text.primary' : 'text.secondary',\n              bgcolor: on ? 'action.selected' : 'transparent',\n              '&:hover': { bgcolor: 'action.hover', color: 'text.primary' },\n              '&:focus-visible': { outline: '2px solid', outlineColor: colorPalette[accent][500], outlineOffset: -2 },\n              ...TAP,\n            }}\n          >\n            {n.icon}\n            <Box component=\"span\" sx={{ flex: 1, textAlign: 'left' }}>\n              {n.label}\n            </Box>\n            {n.id === 'orders' && pending > 0 && <Chip size=\"xs\" variant=\"soft\" color=\"warning\" label={pending} aria-label={`${pending} pending`} />}\n          </ButtonBase>\n        );\n      })}\n    </Box>\n  );\n\n  const brand = (\n    <Stack direction=\"row\" spacing={1.25} sx={{ alignItems: 'center' }}>\n      <Box aria-hidden sx={{ width: 30, height: 30, borderRadius: '10px', display: 'grid', placeItems: 'center', bgcolor: colorPalette[accent][600] }}>\n        <svg width=\"16\" height=\"16\" viewBox=\"0 0 16 16\">\n          <path d=\"M13.5 2.5C7 2.5 3 6 3 11.5c0 .7.1 1.4.2 2C4.6 9.6 7 7 10.5 5.6 7.8 7.7 6 10.300 5.300 13.500 11 13.500 13.500 9 13.500 2.500Z\" fill=\"#fff\" />\n        </svg>\n      </Box>\n      <Box>\n        <Typography sx={{ fontWeight: 800, fontSize: 15, lineHeight: 1.2 }}>Marlowe Tea</Typography>\n        <Typography sx={{ fontSize: 12, color: 'text.secondary', lineHeight: 1.2 }}>Store admin</Typography>\n      </Box>\n    </Stack>\n  );\n\n  // ---------------------------------------------------------------- Overview\n  const overview = (\n    <Stack spacing={2.5}>\n      <ViewHeader\n        headingRef={heading}\n        title=\"Overview\"\n        sub={\n          <>\n            {stats.from} to {stats.to}, compared with the {stats.days} days before\n          </>\n        }\n        action={\n          <Tabs\n            size=\"sm\"\n            variant=\"soft\"\n            color={accent}\n            value={range}\n            onChange={(id) => changeRange(id as RangeId)}\n            renderPanels={false}\n            aria-label=\"Date range\"\n            tabs={RANGES.map((r) => ({ id: r.id, label: r.label }))}\n          />\n        }\n      />\n      <Box sx={{ display: 'grid', gap: 2, gridTemplateColumns: 'repeat(2, minmax(0, 1fr))', [CQ.lg]: { gridTemplateColumns: 'repeat(4, minmax(0, 1fr))' } }}>\n        {stats.kpis.map((k) => {\n          const up = k.delta >= 0;\n          return (\n            <Card key={k.id} variant=\"outlined\" sx={{ p: 2, [CQ.sm]: { p: 2.5 } }} data-testid={`kpi-${k.id}`}>\n              <Stack direction=\"row\" spacing={1} sx={{ alignItems: 'flex-start', justifyContent: 'space-between' }}>\n                <Typography sx={{ fontSize: 13, color: 'text.secondary', fontWeight: 500 }}>{k.label}</Typography>\n                <Box sx={{ display: 'none', [CQ.sm]: { display: 'block' } }}>\n                  <Sparkline values={k.spark} accent={accent} width={72} height={26} />\n                </Box>\n              </Stack>\n              <Typography component=\"p\" sx={{ mt: 0.5, fontWeight: 800, fontSize: 22, lineHeight: 1.2, letterSpacing: '-0.02em', fontVariantNumeric: 'tabular-nums', [CQ.sm]: { fontSize: 28 } }}>\n                {loading ? <Skeleton shape=\"text\" width={96} /> : k.value}\n              </Typography>\n              <Stack direction=\"row\" sx={{ alignItems: 'center', mt: 1.25, flexWrap: 'wrap', columnGap: 1, rowGap: 0.5 }}>\n                <Chip\n                  size=\"xs\"\n                  variant=\"soft\"\n                  color={up ? 'success' : 'danger'}\n                  icon={up ? <TrendingUp /> : <TrendingDown />}\n                  label={`${up ? '+' : '−'}${Math.abs(k.delta).toFixed(k.unit === '%' ? 1 : 2)}${k.unit}`}\n                  aria-label={`${up ? 'Up' : 'Down'} ${Math.abs(k.delta).toFixed(k.unit === '%' ? 1 : 2)} ${k.unit === '%' ? 'percent' : 'points'}`}\n                />\n                <Typography sx={{ fontSize: 12, color: 'text.secondary' }}>vs previous</Typography>\n              </Stack>\n            </Card>\n          );\n        })}\n      </Box>\n\n      <Box sx={{ display: 'grid', gap: 2, gridTemplateColumns: 'minmax(0, 1fr)', [CQ.md]: { gridTemplateColumns: 'minmax(0, 2fr) minmax(0, 1fr)' } }}>\n        <Panel\n          title=\"Revenue\"\n          action={\n            <Typography sx={{ fontSize: 13, color: 'text.secondary' }}>\n              <Box component=\"span\" sx={{ fontWeight: 700, color: 'text.primary' }}>\n                {stats.kpis[0].value}\n              </Box>{' '}\n              in {stats.days} days\n            </Typography>\n          }\n        >\n          {loading ? (\n            <Skeleton shape=\"rounded\" height={300} aria-label=\"Loading revenue\" />\n          ) : (\n            <AreaChart\n              label={`Revenue per day, last ${stats.days} days, with the previous ${stats.days} days for comparison`}\n              values={stats.current.map((d) => d.revenue)}\n              compare={stats.previous.map((d) => d.revenue)}\n              labels={stats.current.map((d) => dayLabel(d.date))}\n              accent={accent}\n              format={money}\n            />\n          )}\n        </Panel>\n        <Panel title=\"Sales by channel\">\n          {loading ? <Skeleton shape=\"rounded\" height={236} aria-label=\"Loading channels\" /> : <BarList items={stats.channels} accent={accent} format={money} />}\n        </Panel>\n      </Box>\n\n      <Box sx={{ display: 'grid', gap: 2, gridTemplateColumns: 'minmax(0, 1fr)', [CQ.md]: { gridTemplateColumns: 'minmax(0, 2fr) minmax(0, 1fr)' } }}>\n        <Panel\n          title=\"Latest orders\"\n          action={\n            <Button size=\"sm\" variant=\"ghost\" color={accent} onClick={() => go('orders')}>\n              View all\n            </Button>\n          }\n        >\n          <Table<Order>\n            size=\"sm\"\n            variant=\"plain\"\n            color={accent}\n            aria-label=\"Latest orders\"\n            data={orders.slice(0, 5)}\n            getRowId={(o) => o.id}\n            onRowClick={showOrder}\n            columns={[\n              { id: 'id', header: 'Order', accessor: 'id' },\n              { id: 'customer', header: 'Customer', accessor: 'customer' },\n              { id: 'status', header: 'Status', accessor: 'status', cell: (v) => <StatusChip status={v as OrderStatus} /> },\n              { id: 'total', header: 'Total', accessor: 'total', align: 'right', cell: (v) => money2(v as number) },\n            ]}\n          />\n        </Panel>\n        <Panel title=\"Activity\">\n          <Box component=\"ul\" sx={{ listStyle: 'none', m: 0, p: 0, display: 'grid', gap: 2 }}>\n            {ACTIVITY.map((a) => (\n              <Box component=\"li\" key={a.what} sx={{ display: 'flex', gap: 1.5 }}>\n                <Box aria-hidden sx={{ mt: '7px', width: 8, height: 8, borderRadius: '50%', flexShrink: 0, bgcolor: colorPalette[a.tone][500] }} />\n                <Box sx={{ minWidth: 0 }}>\n                  <Typography sx={{ fontSize: 13, lineHeight: 1.45 }}>\n                    <Box component=\"span\" sx={{ fontWeight: 700 }}>\n                      {a.who}\n                    </Box>{' '}\n                    {a.what}\n                  </Typography>\n                  <Typography sx={{ fontSize: 12, color: 'text.secondary' }}>{a.when}</Typography>\n                </Box>\n              </Box>\n            ))}\n          </Box>\n        </Panel>\n      </Box>\n    </Stack>\n  );\n\n  // ---------------------------------------------------------------- Orders\n  // Narrow containers get three columns: the order number moves under the customer.\n  const columns = narrow\n    ? [\n        {\n          id: 'customer',\n          header: 'Customer',\n          accessor: 'customer' as const,\n          cell: (_: unknown, o: Order) => (\n            <>\n              <Box component=\"span\" sx={{ display: 'block', fontWeight: 600 }}>\n                {o.customer}\n              </Box>\n              <Box component=\"span\" sx={{ display: 'block', fontSize: 12, color: 'text.secondary' }}>\n                {o.id} · {dayLabel(o.date)}\n              </Box>\n            </>\n          ),\n        },\n        { id: 'status', header: 'Status', accessor: 'status' as const, cell: (v: unknown) => <StatusChip status={v as OrderStatus} /> },\n        { id: 'total', header: 'Total', accessor: 'total' as const, align: 'right' as const, cell: (v: unknown) => money2(v as number) },\n      ]\n    : [\n        { id: 'id', header: 'Order', accessor: 'id' as const },\n        { id: 'customer', header: 'Customer', accessor: 'customer' as const },\n        { id: 'date', header: 'Date', accessor: 'date' as const, cell: (v: unknown) => dayLabel(v as number) },\n        { id: 'channel', header: 'Channel', accessor: 'channel' as const, sortable: false },\n        { id: 'status', header: 'Status', accessor: 'status' as const, cell: (v: unknown) => <StatusChip status={v as OrderStatus} /> },\n        { id: 'total', header: 'Total', accessor: 'total' as const, align: 'right' as const, cell: (v: unknown) => money2(v as number) },\n      ];\n\n  const ordersView = (\n    <Stack spacing={2.5}>\n      <ViewHeader\n        headingRef={heading}\n        title=\"Orders\"\n        sub={`${filtered.length} ${filtered.length === 1 ? 'order' : 'orders'}${status !== 'All' || needle ? ' match your filters' : ' in the last 12 days'}`}\n        action={\n          <Button color={accent} startIcon={<Add />} onClick={() => { setDraft({ customer: '', amount: '' }); setNewOpen(true); }}>\n            New order\n          </Button>\n        }\n      />\n      <Card variant=\"outlined\" sx={{ p: 0, overflow: 'hidden' }}>\n        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5, p: 2, [CQ.md]: { flexDirection: 'row', alignItems: 'center' } }}>\n          <TextField\n            size=\"sm\"\n            variant=\"outlined\"\n            color={accent}\n            placeholder=\"Search orders\"\n            value={query}\n            onChange={(e) => { setQuery(e.target.value); setPage(1); }}\n            startIcon={<Search fontSize=\"small\" />}\n            slotProps={{ htmlInput: { 'aria-label': 'Search orders' } }}\n            sx={{ [CQ.md]: { width: 280 } }}\n          />\n          <Stack direction=\"row\" spacing={0.5} role=\"group\" aria-label=\"Filter by status\" sx={{ flexWrap: 'wrap', rowGap: 0.5 }}>\n            {(['All', 'Paid', 'Pending', 'Refunded', 'Failed'] as const).map((s) => (\n              <Button key={s} size=\"sm\" color={accent} variant={status === s ? 'soft' : 'ghost'} aria-pressed={status === s} onClick={() => { setStatus(s); setPage(1); }} sx={TAP}>\n                {s}\n              </Button>\n            ))}\n          </Stack>\n        </Box>\n        <Divider />\n        <Table<Order>\n          variant=\"plain\"\n          size={narrow ? 'sm' : 'md'}\n          color={accent}\n          aria-label=\"Orders\"\n          data={pageRows}\n          getRowId={(o) => o.id}\n          onRowClick={showOrder}\n          sortable\n          sortBy={sort.by}\n          sortDirection={sort.dir}\n          onSortChange={(by, dir) => setSort({ by: by as SortKey, dir })}\n          columns={columns}\n          emptyContent={\n            <Empty\n              title=\"No orders match\"\n              body=\"Try a different search or clear the status filter.\"\n              action={\n                <Button size=\"sm\" variant=\"soft\" color={accent} onClick={() => { setQuery(''); setStatus('All'); }}>\n                  Clear filters\n                </Button>\n              }\n            />\n          }\n        />\n        <Stack direction=\"row\" sx={{ alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 1.5, px: 2, py: 1.5 }}>\n          <Typography sx={{ fontSize: 13, color: 'text.secondary' }} role=\"status\">\n            {filtered.length === 0 ? 'Showing 0 orders' : `Showing ${(current - 1) * PAGE_SIZE + 1} to ${Math.min(current * PAGE_SIZE, filtered.length)} of ${filtered.length}`}\n          </Typography>\n          {pages > 1 && <Pagination size=\"sm\" color={accent} count={pages} page={current} onChange={(_, p) => setPage(p)} siblingCount={narrow ? 0 : 1} aria-label=\"Orders pages\" />}\n        </Stack>\n      </Card>\n    </Stack>\n  );\n\n  // ---------------------------------------------------------------- Customers\n  const people = CUSTOMERS.filter((c) => `${c.name} ${c.city} ${c.email}`.toLowerCase().includes(customerQuery.trim().toLowerCase()));\n  const customersView = (\n    <Stack spacing={2.5}>\n      <ViewHeader\n        headingRef={heading}\n        title=\"Customers\"\n        sub={`${people.length} of ${CUSTOMERS.length} people who ordered in the last 12 days`}\n        action={\n          <TextField\n            size=\"sm\"\n            variant=\"outlined\"\n            color={accent}\n            placeholder=\"Search customers\"\n            value={customerQuery}\n            onChange={(e) => setCustomerQuery(e.target.value)}\n            startIcon={<Search fontSize=\"small\" />}\n            slotProps={{ htmlInput: { 'aria-label': 'Search customers' } }}\n            sx={{ width: '100%', [CQ.sm]: { width: 260 } }}\n          />\n        }\n      />\n      {people.length === 0 ? (\n        <Card variant=\"outlined\" sx={{ p: 3 }}>\n          <Empty title=\"No customers found\" body={`Nobody matches \"${customerQuery.trim()}\".`} action={<Button size=\"sm\" variant=\"soft\" color={accent} onClick={() => setCustomerQuery('')}>Clear search</Button>} />\n        </Card>\n      ) : (\n        <Box sx={{ display: 'grid', gap: 2, gridTemplateColumns: 'repeat(auto-fill, minmax(232px, 1fr))' }}>\n          {people.map((c) => {\n            const s = statsFor(c.name);\n            return (\n              <Card key={c.name} variant=\"outlined\" sx={{ p: 0, overflow: 'hidden', '&:hover, &:focus-within': { borderColor: colorPalette[accent][500] } }}>\n                <ButtonBase\n                  onClick={() => { setCustomer(c); setCustomerOpen(true); }}\n                  aria-label={`Open ${c.name}`}\n                  sx={{ display: 'block', width: '100%', p: 2, textAlign: 'left', '&:focus-visible': { outline: '2px solid', outlineColor: colorPalette[accent][500], outlineOffset: -2 } }}\n                >\n                  <Stack direction=\"row\" spacing={1.5} sx={{ alignItems: 'center' }}>\n                    <Avatar variant=\"soft\" color={accent}>{initials(c.name)}</Avatar>\n                    <Box sx={{ minWidth: 0, flex: 1 }}>\n                      <Typography noWrap sx={{ fontWeight: 700, fontSize: 14 }}>\n                        {c.name}\n                      </Typography>\n                      <Typography noWrap sx={{ fontSize: 13, color: 'text.secondary' }}>\n                        {c.city}\n                      </Typography>\n                    </Box>\n                    <Chip size=\"xs\" variant=\"soft\" color={c.tier === 'Member' ? accent : 'neutral'} label={c.tier} />\n                  </Stack>\n                  <Stack direction=\"row\" sx={{ justifyContent: 'space-between', mt: 2, fontSize: 13 }}>\n                    <Box component=\"span\" sx={{ color: 'text.secondary' }}>\n                      {s.count} {s.count === 1 ? 'order' : 'orders'}\n                    </Box>\n                    <Box component=\"span\" sx={{ fontWeight: 700, fontVariantNumeric: 'tabular-nums' }}>\n                      {money2(s.spent)}\n                    </Box>\n                  </Stack>\n                </ButtonBase>\n              </Card>\n            );\n          })}\n        </Box>\n      )}\n    </Stack>\n  );\n\n  const detail = customer && statsFor(customer.name);\n\n  return (\n    <Box ref={root} sx={{ containerType: 'inline-size', display: 'flex', height: '100%', minHeight: 600, bgcolor: 'background.default', color: 'text.primary' }}>\n      {/* Sidebar: shown when the container is at least 900px wide. */}\n      <Box component=\"aside\" aria-label=\"Sidebar\" sx={{ display: 'none', [CQ.md]: { display: 'flex' }, flexDirection: 'column', width: 232, flexShrink: 0, borderRight: 1, borderColor: 'divider', bgcolor: 'background.paper' }}>\n        <Box sx={{ px: 2.5, py: 2.25 }}>{brand}</Box>\n        <Divider />\n        {nav}\n        <Box sx={{ mt: 'auto', p: 1.5 }}>\n          <Stack direction=\"row\" spacing={1.25} sx={{ alignItems: 'center', p: 1.25, borderRadius: '10px', border: 1, borderColor: 'divider' }}>\n            <Avatar size=\"sm\" variant=\"solid\" color={accent} status=\"online\">\n              IC\n            </Avatar>\n            <Box sx={{ minWidth: 0 }}>\n              <Typography noWrap sx={{ fontSize: 13, fontWeight: 700 }}>\n                Ines Castillo\n              </Typography>\n              <Typography noWrap sx={{ fontSize: 12, color: 'text.secondary' }}>\n                Owner\n              </Typography>\n            </Box>\n          </Stack>\n        </Box>\n      </Box>\n\n      <Drawer\n        open={navOpen}\n        onClose={() => setNavOpen(false)}\n        anchor=\"left\"\n        aria-label=\"Navigation\"\n        slotProps={{\n          transition: {\n            onExited: () => {\n              if (!focusHeadingOnClose.current) return;\n              focusHeadingOnClose.current = false;\n              heading.current?.focus();\n            },\n          },\n        }}\n      >\n        <Box sx={{ width: 264 }}>\n          <Stack direction=\"row\" sx={{ alignItems: 'center', justifyContent: 'space-between', pl: 2.5, pr: 1, py: 1.5 }}>\n            {brand}\n            <IconButton aria-label=\"Close navigation\" onClick={() => setNavOpen(false)} sx={TAP}>\n              <Close />\n            </IconButton>\n          </Stack>\n          <Divider />\n          {nav}\n        </Box>\n      </Drawer>\n\n      <Box sx={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column' }}>\n        <Stack component=\"header\" direction=\"row\" spacing={1} sx={{ alignItems: 'center', px: 2, minHeight: 56, borderBottom: 1, borderColor: 'divider', bgcolor: 'background.paper', flexShrink: 0, [CQ.md]: { px: 3 } }}>\n          <IconButton aria-label=\"Open navigation\" aria-expanded={navOpen} onClick={() => setNavOpen(true)} edge=\"start\" sx={{ [CQ.md]: { display: 'none' }, ...TAP }}>\n            <MenuIcon />\n          </IconButton>\n          <Typography sx={{ flex: 1, minWidth: 0, fontSize: 14, color: 'text.secondary' }} noWrap>\n            <Box component=\"span\" sx={{ display: 'none', [CQ.sm]: { display: 'inline' } }}>\n              Marlowe Tea /{' '}\n            </Box>\n            <Box component=\"span\" sx={{ color: 'text.primary', fontWeight: 700 }}>\n              {NAV.find((n) => n.id === view)!.label}\n            </Box>\n          </Typography>\n          <Box sx={{ display: 'none', [CQ.sm]: { display: 'block' } }}>\n            <Button size=\"sm\" variant=\"outlined\" color=\"neutral\" startIcon={<FileDownloadOutlined />} onClick={() => notify('Report exported as CSV')}>\n              Export\n            </Button>\n          </Box>\n          <IconButton aria-label=\"Notifications, 3 unread\" sx={TAP}>\n            <Badge badgeContent={3} color=\"danger\">\n              <NotificationsNoneOutlined />\n            </Badge>\n          </IconButton>\n        </Stack>\n\n        <Box component=\"section\" aria-label={NAV.find((n) => n.id === view)!.label} sx={{ flex: 1, minHeight: 0, overflowY: 'auto', p: 2, [CQ.md]: { p: 3 } }}>\n          <Box sx={{ maxWidth: 1240, mx: 'auto' }}>{view === 'overview' ? overview : view === 'orders' ? ordersView : customersView}</Box>\n        </Box>\n      </Box>\n\n      {/* Order details */}\n      <Dialog\n        open={orderOpen}\n        onClose={() => setOrderOpen(false)}\n        maxWidth=\"xs\"\n        fullWidth\n        aria-labelledby={titleId}\n        slotProps={{\n          transition: {\n            onExited: () => {\n              setOpenOrder(null);\n              // The row may have re-rendered (after a refund); put focus back on it.\n              if (returnFocus.current?.isConnected) returnFocus.current.focus();\n              returnFocus.current = null;\n            },\n          },\n        }}\n      >\n        {openOrder && (\n          <>\n            <DialogTitle id={titleId}>Order {openOrder.id}</DialogTitle>\n            <DialogContent>\n              <Stack direction=\"row\" spacing={1.5} sx={{ alignItems: 'center', pt: 0.5 }}>\n                <Avatar variant=\"soft\" color={accent}>{initials(openOrder.customer)}</Avatar>\n                <Box sx={{ minWidth: 0, flex: 1 }}>\n                  <Typography noWrap sx={{ fontWeight: 700 }}>\n                    {openOrder.customer}\n                  </Typography>\n                  <Typography noWrap variant=\"body2\" color=\"text.secondary\">\n                    {openOrder.email}\n                  </Typography>\n                </Box>\n                <StatusChip status={openOrder.status} />\n              </Stack>\n              <Typography variant=\"body2\" color=\"text.secondary\" sx={{ mt: 2 }}>\n                {dayLabel(openOrder.date)}, 2026 · {openOrder.channel}\n              </Typography>\n              <Box component=\"ul\" sx={{ listStyle: 'none', m: 0, mt: 1.5, p: 0, borderTop: 1, borderColor: 'divider' }}>\n                {openOrder.lines.map((l) => (\n                  <Box component=\"li\" key={l.name} sx={{ display: 'flex', gap: 1.5, py: 1.25, borderBottom: 1, borderColor: 'divider', fontSize: 14 }}>\n                    <Box component=\"span\" sx={{ flex: 1, minWidth: 0 }}>\n                      {l.name}\n                      <Box component=\"span\" sx={{ color: 'text.secondary' }}>\n                        {' '}\n                        × {l.qty}\n                      </Box>\n                    </Box>\n                    <Box component=\"span\" sx={{ fontVariantNumeric: 'tabular-nums' }}>\n                      {money2(l.price * l.qty)}\n                    </Box>\n                  </Box>\n                ))}\n              </Box>\n              <Stack direction=\"row\" sx={{ justifyContent: 'space-between', mt: 1.5 }}>\n                <Typography sx={{ fontWeight: 700 }}>Total</Typography>\n                <Typography sx={{ fontWeight: 800, fontVariantNumeric: 'tabular-nums' }}>{money2(openOrder.total)}</Typography>\n              </Stack>\n            </DialogContent>\n            <DialogActions>\n              {openOrder.status === 'Paid' && (\n                <Button\n                  variant=\"ghost\"\n                  color=\"danger\"\n                  onClick={() => {\n                    setOrders((list) => list.map((o) => (o.id === openOrder.id ? { ...o, status: 'Refunded' } : o)));\n                    notify(`Order ${openOrder.id} refunded`);\n                    setOrderOpen(false);\n                  }}\n                >\n                  Refund\n                </Button>\n              )}\n              <Button color={accent} onClick={() => setOrderOpen(false)}>\n                Done\n              </Button>\n            </DialogActions>\n          </>\n        )}\n      </Dialog>\n\n      {/* New order: a real form, so Enter submits. It opens empty every time. */}\n      <Dialog open={newOpen} onClose={() => setNewOpen(false)} maxWidth=\"xs\" fullWidth aria-labelledby={newTitleId}>\n        <DialogTitle id={newTitleId}>New order</DialogTitle>\n        <Box component=\"form\" noValidate sx={{ display: 'contents' }} onSubmit={(e: React.FormEvent) => { e.preventDefault(); createOrder(); }}>\n          <DialogContent>\n            <Stack spacing={2} sx={{ pt: 1 }}>\n              <TextField label=\"Customer name\" color={accent} value={draft.customer} onChange={(e) => setDraft((d) => ({ ...d, customer: e.target.value }))} fullWidth autoFocus />\n              <TextField\n                label=\"Amount (USD)\"\n                type=\"number\"\n                color={accent}\n                value={draft.amount}\n                onChange={(e) => setDraft((d) => ({ ...d, amount: e.target.value }))}\n                fullWidth\n                error={draft.amount !== '' && !amountOk}\n                helperText={draft.amount !== '' && !amountOk ? 'Enter an amount above 0' : ' '}\n              />\n            </Stack>\n          </DialogContent>\n          <DialogActions>\n            <Button variant=\"ghost\" color=\"neutral\" onClick={() => setNewOpen(false)}>\n              Cancel\n            </Button>\n            <Button type=\"submit\" color={accent} disabled={!draft.customer.trim() || !amountOk}>\n              Create order\n            </Button>\n          </DialogActions>\n        </Box>\n      </Dialog>\n\n      {/* Customer details */}\n      <Drawer open={customerOpen} onClose={() => setCustomerOpen(false)} anchor=\"right\" aria-label={customer?.name ?? 'Customer'} slotProps={{ transition: { onExited: () => setCustomer(null) } }}>\n        {customer && detail && (\n          <Box sx={{ width: 'min(360px, 86cqw)', minWidth: 280, p: 2.5 }}>\n            <Stack direction=\"row\" sx={{ justifyContent: 'space-between', alignItems: 'center' }}>\n              <Typography component=\"h2\" sx={{ fontWeight: 800, fontSize: 18 }}>\n                {customer.name}\n              </Typography>\n              <IconButton aria-label=\"Close details\" onClick={() => setCustomerOpen(false)} edge=\"end\" sx={TAP}>\n                <Close />\n              </IconButton>\n            </Stack>\n            <Typography variant=\"body2\" color=\"text.secondary\">\n              {customer.email} · {customer.city}\n            </Typography>\n            <Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 1, my: 2.5 }}>\n              {[\n                ['Orders', String(detail.count)],\n                ['Spent', money(detail.spent)],\n                ['Since', customer.since],\n              ].map(([k, v]) => (\n                <Box key={k} sx={{ p: 1.25, borderRadius: '10px', border: 1, borderColor: 'divider' }}>\n                  <Typography sx={{ fontSize: 12, color: 'text.secondary' }}>{k}</Typography>\n                  <Typography sx={{ fontWeight: 700, fontSize: 14 }}>{v}</Typography>\n                </Box>\n              ))}\n            </Box>\n            <Typography component=\"h3\" sx={{ fontWeight: 700, fontSize: 14, mb: 1 }}>\n              Recent orders\n            </Typography>\n            {detail.own.length === 0 ? (\n              <Typography variant=\"body2\" color=\"text.secondary\">\n                No orders in the last 12 days.\n              </Typography>\n            ) : (\n              <Box component=\"ul\" sx={{ listStyle: 'none', m: 0, p: 0 }}>\n                {detail.own.slice(0, 5).map((o) => (\n                  <Box component=\"li\" key={o.id} sx={{ display: 'flex', alignItems: 'center', gap: 1, py: 1, borderBottom: 1, borderColor: 'divider', fontSize: 13 }}>\n                    <Box component=\"span\" sx={{ fontWeight: 600 }}>\n                      {o.id}\n                    </Box>\n                    <Box component=\"span\" sx={{ color: 'text.secondary', flex: 1 }}>\n                      {dayLabel(o.date)}\n                    </Box>\n                    <StatusChip status={o.status} />\n                    <Box component=\"span\" sx={{ width: 64, textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>\n                      {money2(o.total)}\n                    </Box>\n                  </Box>\n                ))}\n              </Box>\n            )}\n            <Button\n              fullWidth\n              variant=\"soft\"\n              color={accent}\n              sx={{ mt: 2.5 }}\n              onClick={() => {\n                notify(`Email drafted to ${customer.name}`);\n                setCustomerOpen(false);\n              }}\n            >\n              Send email\n            </Button>\n          </Box>\n        )}\n      </Drawer>\n\n      <Snackbar\n        key={toast?.id ?? 0}\n        open={toast?.open ?? false}\n        autoHideDuration={3000}\n        onClose={(_, reason) => {\n          if (reason !== 'clickaway') setToast((t) => (t ? { ...t, open: false } : t));\n        }}\n        message={toast?.message ?? ''}\n        color=\"success\"\n        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}\n      />\n    </Box>\n  );\n}\n"},{"file":"charts.tsx","source":"'use client';\n// Hand-written SVG charts: no chart library. The area chart sizes itself to its\n// container, shows a crosshair and tooltip on hover or touch, and can be read with\n// the arrow keys. Text uses the theme's text colors; only the marks carry the accent.\nimport * as React from 'react';\nimport { Box, Typography } from '@mui/material';\nimport { useTheme } from '@mui/material/styles';\nimport { motion, useReducedMotion } from 'motion/react';\nimport { colorPalette } from '@sorbet-ui/tokens';\nimport type { Accent } from './data';\n\n/** Mark color for an accent: darker on light surfaces, lighter on dark ones. */\nexport function useMarkColor(accent: Accent) {\n  const dark = useTheme().palette.mode === 'dark';\n  return { line: colorPalette[accent][dark ? 400 : 600], soft: colorPalette[accent][dark ? 400 : 500], dark };\n}\n\n// False for the server render and the first client render, so charts are fully drawn in\n// the static HTML; later data changes animate in.\nfunction useAnimateChanges() {\n  const [on, setOn] = React.useState(false);\n  React.useEffect(() => setOn(true), []);\n  return on;\n}\n\nconst SR_ONLY = { position: 'absolute', width: '1px', height: '1px', overflow: 'hidden', clip: 'rect(0 0 0 0)', whiteSpace: 'nowrap' } as const;\n\n// 1, 2, 2.5 or 5 times a power of ten: axis maximums people can read.\nfunction niceMax(value: number) {\n  const pow = 10 ** Math.floor(Math.log10(value));\n  const step = [1, 2, 2.5, 5, 10].find((m) => m * pow >= value) ?? 10;\n  return step * pow;\n}\n\nexport type AreaChartProps = {\n  /** Accessible name, e.g. \"Revenue per day, last 30 days\". */\n  label: string;\n  values: number[];\n  /** The period before, drawn as a dashed line. */\n  compare: number[];\n  /** One label per point (dates). */\n  labels: string[];\n  accent: Accent;\n  format: (n: number) => string;\n  height?: number;\n};\n\nexport function AreaChart({ label, values, compare, labels, accent, format, height = 264 }: AreaChartProps) {\n  const reduce = useReducedMotion();\n  const theme = useTheme();\n  const { line, dark } = useMarkColor(accent);\n  const wrap = React.useRef<HTMLDivElement>(null);\n  const [width, setWidth] = React.useState(720);\n  const [active, setActive] = React.useState<number | null>(null);\n  const gradient = React.useId();\n  const animateIn = useAnimateChanges();\n\n  React.useEffect(() => {\n    const el = wrap.current;\n    if (!el) return;\n    const ro = new ResizeObserver(([entry]) => setWidth(Math.max(240, Math.round(entry.contentRect.width))));\n    ro.observe(el);\n    return () => ro.disconnect();\n  }, []);\n\n  const pad = { top: 12, right: 12, bottom: 28, left: 48 };\n  const w = width - pad.left - pad.right;\n  const h = height - pad.top - pad.bottom;\n  const n = values.length;\n  const max = niceMax(Math.max(...values, ...compare));\n  const x = (i: number) => pad.left + (n === 1 ? w / 2 : (i / (n - 1)) * w);\n  const y = (v: number) => pad.top + h - (v / max) * h;\n  const path = (list: number[]) => list.map((v, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)},${y(v).toFixed(1)}`).join('');\n  const area = `${path(values)}L${x(n - 1).toFixed(1)},${pad.top + h}L${x(0).toFixed(1)},${pad.top + h}Z`;\n  const grid = [0, 0.25, 0.5, 0.75, 1].map((t) => max * t);\n  // About one date label per 110px, always including the first and last point.\n  const tickCount = Math.max(2, Math.min(n, Math.floor(w / 110) + 1));\n  const ticks = Array.from({ length: tickCount }, (_, i) => Math.round((i / (tickCount - 1)) * (n - 1)));\n  const muted = theme.palette.text.secondary;\n  const rule = dark ? 'rgba(148,163,184,.18)' : 'rgba(15,23,42,.08)';\n\n  const fromPointer = (e: React.PointerEvent) => {\n    const box = wrap.current!.getBoundingClientRect();\n    const t = (e.clientX - box.left - pad.left) / w;\n    setActive(Math.max(0, Math.min(n - 1, Math.round(t * (n - 1)))));\n  };\n  const onKeyDown = (e: React.KeyboardEvent) => {\n    const at = active ?? n - 1;\n    const next = { ArrowLeft: at - 1, ArrowRight: at + 1, Home: 0, End: n - 1 }[e.key];\n    if (next === undefined) {\n      if (e.key === 'Escape') setActive(null);\n      return;\n    }\n    e.preventDefault();\n    setActive(Math.max(0, Math.min(n - 1, next)));\n  };\n\n  const tipLeft = active === null ? 0 : x(active);\n  const flip = tipLeft > width * 0.6;\n\n  return (\n    <Box>\n      <Box\n        ref={wrap}\n        role=\"group\"\n        aria-roledescription=\"chart\"\n        aria-label={`${label}. Use the left and right arrow keys to read each point.`}\n        tabIndex={0}\n        data-testid=\"area-chart\"\n        data-points={n}\n        onPointerMove={fromPointer}\n        onPointerDown={fromPointer}\n        onPointerLeave={() => setActive(null)}\n        onFocus={() => setActive((a) => a ?? n - 1)}\n        onBlur={() => setActive(null)}\n        onKeyDown={onKeyDown}\n        sx={{ position: 'relative', height, touchAction: 'pan-y', cursor: 'crosshair', borderRadius: '10px', outlineOffset: 4, '&:focus-visible': { outline: `2px solid ${line}` } }}\n      >\n        <svg width={width} height={height} aria-hidden style={{ display: 'block', maxWidth: '100%' }}>\n          <defs>\n            <linearGradient id={gradient} x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n              <stop offset=\"0%\" stopColor={line} stopOpacity={dark ? 0.32 : 0.22} />\n              <stop offset=\"100%\" stopColor={line} stopOpacity={0} />\n            </linearGradient>\n          </defs>\n          {grid.map((g) => (\n            <g key={g}>\n              <line x1={pad.left} x2={width - pad.right} y1={y(g)} y2={y(g)} stroke={rule} />\n              <text x={pad.left - 10} y={y(g) + 4} textAnchor=\"end\" fontSize=\"11\" fill={muted} style={{ fontVariantNumeric: 'tabular-nums' }}>\n                {format(g)}\n              </text>\n            </g>\n          ))}\n          {ticks.map((i, k) => (\n            <text key={i} x={x(i)} y={height - 8} fontSize=\"11\" fill={muted} textAnchor={k === 0 ? 'start' : k === ticks.length - 1 ? 'end' : 'middle'}>\n              {labels[i]}\n            </text>\n          ))}\n          <path d={path(compare)} fill=\"none\" stroke={muted} strokeOpacity={0.55} strokeWidth={1.5} strokeDasharray=\"4 5\" strokeLinecap=\"round\" />\n          <motion.path key={`a-${n}`} d={area} fill={`url(#${gradient})`} initial={animateIn ? { opacity: 0 } : false} animate={{ opacity: 1 }} transition={reduce ? { duration: 0 } : { duration: 0.6, delay: 0.25 }} />\n          <motion.path\n            key={`l-${n}`}\n            d={path(values)}\n            fill=\"none\"\n            stroke={line}\n            strokeWidth={2}\n            strokeLinejoin=\"round\"\n            strokeLinecap=\"round\"\n            initial={animateIn ? { pathLength: 0 } : false}\n            animate={{ pathLength: 1 }}\n            transition={{ duration: reduce ? 0 : 0.9, ease: [0.22, 1, 0.36, 1] }}\n          />\n          {active !== null && (\n            <g>\n              <line x1={x(active)} x2={x(active)} y1={pad.top} y2={pad.top + h} stroke={muted} strokeOpacity={0.5} />\n              <circle cx={x(active)} cy={y(compare[active])} r={3.5} fill={theme.palette.background.paper} stroke={muted} strokeWidth={1.5} />\n              <circle cx={x(active)} cy={y(values[active])} r={5} fill={line} stroke={theme.palette.background.paper} strokeWidth={2} />\n            </g>\n          )}\n        </svg>\n        {active !== null && (\n          <Box\n            data-testid=\"chart-tooltip\"\n            sx={{\n              position: 'absolute',\n              top: 8,\n              left: tipLeft,\n              transform: flip ? 'translateX(calc(-100% - 12px))' : 'translateX(12px)',\n              pointerEvents: 'none',\n              minWidth: 148,\n              px: 1.5,\n              py: 1,\n              borderRadius: '10px',\n              border: 1,\n              borderColor: 'divider',\n              bgcolor: 'background.paper',\n              boxShadow: dark ? '0 8px 24px rgba(0,0,0,.5)' : '0 8px 24px rgba(15,23,42,.12)',\n            }}\n          >\n            <Typography sx={{ fontSize: 12, fontWeight: 700 }}>{labels[active]}</Typography>\n            <TipRow swatch={<Box sx={{ width: 10, height: 10, borderRadius: '50%', bgcolor: line }} />} name=\"This period\" value={format(values[active])} />\n            <TipRow swatch={<Box sx={{ width: 10, borderTop: '2px dashed', borderColor: 'text.secondary' }} />} name=\"Previous\" value={format(compare[active])} />\n          </Box>\n        )}\n        <Box component=\"span\" aria-live=\"polite\" sx={SR_ONLY}>\n          {active !== null ? `${labels[active]}: ${format(values[active])}, previous period ${format(compare[active])}` : ''}\n        </Box>\n      </Box>\n      <Box sx={{ display: 'flex', gap: 2.5, mt: 1.5, pl: `${pad.left}px` }}>\n        <Legend swatch={<Box sx={{ width: 14, height: 3, borderRadius: '10px', bgcolor: line }} />} name=\"This period\" />\n        <Legend swatch={<Box sx={{ width: 14, borderTop: '2px dashed', borderColor: 'text.secondary' }} />} name=\"Previous period\" />\n      </Box>\n    </Box>\n  );\n}\n\nfunction TipRow({ swatch, name, value }: { swatch: React.ReactNode; name: string; value: string }) {\n  return (\n    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 0.5, fontSize: 12 }}>\n      {swatch}\n      <Box component=\"span\" sx={{ color: 'text.secondary', flex: 1 }}>\n        {name}\n      </Box>\n      <Box component=\"span\" sx={{ fontWeight: 700, fontVariantNumeric: 'tabular-nums' }}>\n        {value}\n      </Box>\n    </Box>\n  );\n}\n\nfunction Legend({ swatch, name }: { swatch: React.ReactNode; name: string }) {\n  return (\n    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.75, fontSize: 12, color: 'text.secondary' }}>\n      {swatch}\n      {name}\n    </Box>\n  );\n}\n\n/** Horizontal bars with the value and share written next to each one. */\nexport function BarList({ items, accent, format }: { items: { name: string; value: number }[]; accent: Accent; format: (n: number) => string }) {\n  const { soft, dark } = useMarkColor(accent);\n  const reduce = useReducedMotion();\n  const animateIn = useAnimateChanges();\n  const total = items.reduce((a, b) => a + b.value, 0);\n  const max = Math.max(...items.map((i) => i.value));\n  return (\n    <Box component=\"ul\" sx={{ listStyle: 'none', m: 0, p: 0, display: 'grid', gap: 1.75 }}>\n      {items.map((item, i) => (\n        <Box component=\"li\" key={item.name}>\n          <Box sx={{ display: 'flex', alignItems: 'baseline', gap: 1, fontSize: 13 }}>\n            <Box component=\"span\" sx={{ flex: 1, minWidth: 0, fontWeight: 600 }}>\n              {item.name}\n            </Box>\n            <Box component=\"span\" sx={{ fontVariantNumeric: 'tabular-nums', fontWeight: 700 }}>\n              {format(item.value)}\n            </Box>\n            <Box component=\"span\" sx={{ width: 36, textAlign: 'right', color: 'text.secondary', fontVariantNumeric: 'tabular-nums' }}>\n              {Math.round((item.value / total) * 100)}%\n            </Box>\n          </Box>\n          <Box aria-hidden sx={{ mt: 0.75, height: 8, borderRadius: '4px', bgcolor: dark ? 'rgba(148,163,184,.14)' : 'rgba(15,23,42,.06)', overflow: 'hidden' }}>\n            <motion.div\n              key={item.value}\n              initial={animateIn ? { width: 0 } : false}\n              animate={{ width: `${(item.value / max) * 100}%` }}\n              transition={reduce ? { duration: 0 } : { duration: 0.6, delay: i * 0.05, ease: [0.22, 1, 0.36, 1] }}\n              style={{ height: '100%', borderRadius: 4, background: soft, opacity: 1 - i * 0.14 }}\n            />\n          </Box>\n        </Box>\n      ))}\n    </Box>\n  );\n}\n\n/** Tiny trend line for a KPI card. Decorative: the number beside it carries the value. */\nexport function Sparkline({ values, accent, width = 96, height = 32 }: { values: number[]; accent: Accent; width?: number; height?: number }) {\n  const { line } = useMarkColor(accent);\n  const min = Math.min(...values);\n  const span = Math.max(...values) - min || 1;\n  const points = values.map((v, i) => `${((i / (values.length - 1)) * width).toFixed(1)},${(height - 3 - ((v - min) / span) * (height - 6)).toFixed(1)}`).join(' ');\n  return (\n    <svg aria-hidden width={width} height={height} viewBox={`0 0 ${width} ${height}`} style={{ display: 'block', flexShrink: 0 }}>\n      <polyline points={points} fill=\"none\" stroke={line} strokeWidth={1.75} strokeLinejoin=\"round\" strokeLinecap=\"round\" />\n    </svg>\n  );\n}\n"},{"file":"data.ts","source":"// Sample data for the Marlowe Tea dashboard. Everything is generated from a fixed\n// seed, so the server and the browser render the same numbers, and every total on\n// screen is computed from these rows (KPIs, chart, channels and customers add up).\n\nexport type Accent = 'primary' | 'secondary' | 'success' | 'warning' | 'danger' | 'info';\n\n// Small seeded generator (mulberry32): the same sequence on every run.\nfunction seeded(seed: number) {\n  let a = seed;\n  return () => {\n    a = (a + 0x6d2b79f5) | 0;\n    let t = Math.imul(a ^ (a >>> 15), 1 | a);\n    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;\n    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n  };\n}\n\nconst MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];\nconst DAY = 86_400_000;\n/** \"Today\" in the sample: fixed, so screenshots and tests never drift. */\nexport const TODAY = Date.UTC(2026, 10, 11);\nexport const dayLabel = (ms: number) => {\n  const d = new Date(ms);\n  return `${MONTHS[d.getUTCMonth()]} ${d.getUTCDate()}`;\n};\nexport const money = (n: number) => `$${Math.round(n).toLocaleString('en-US')}`;\nexport const money2 = (n: number) => `$${n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;\n\n// ---------------------------------------------------------------- Daily metrics\nexport type Day = { date: number; revenue: number; orders: number; sessions: number };\n\n// 180 days: the last 90 are shown, the 90 before them are the comparison period.\nexport const DAYS: Day[] = (() => {\n  const rand = seeded(7);\n  // Weekends sell more tea. Sunday first.\n  const week = [1.18, 0.9, 0.86, 0.92, 0.98, 1.1, 1.26];\n  return Array.from({ length: 180 }, (_, i) => {\n    const date = TODAY - (179 - i) * DAY;\n    const trend = 1180 + i * 5.2;\n    const promo = i > 150 && i < 158 ? 1.35 : 1; // a late-October sale\n    const revenue = Math.round(trend * week[new Date(date).getUTCDay()] * promo * (0.88 + rand() * 0.24));\n    const orders = Math.max(1, Math.round(revenue / (36 + rand() * 6)));\n    const sessions = Math.round(orders / (0.029 + rand() * 0.008 + i * 0.00002));\n    return { date, revenue, orders, sessions };\n  });\n})();\n\nexport const RANGES = [\n  { id: '7d', label: '7 days', days: 7 },\n  { id: '30d', label: '30 days', days: 30 },\n  { id: '90d', label: '90 days', days: 90 },\n] as const;\nexport type RangeId = (typeof RANGES)[number]['id'];\n\nconst sum = (list: number[]) => list.reduce((a, b) => a + b, 0);\nconst change = (now: number, before: number) => ((now - before) / before) * 100;\n\n/** Everything the overview shows for one range, with the period before it for comparison. */\nexport function summarize(range: RangeId) {\n  const n = RANGES.find((r) => r.id === range)!.days;\n  const current = DAYS.slice(-n);\n  const previous = DAYS.slice(-2 * n, -n);\n  const total = (rows: Day[]) => {\n    const revenue = sum(rows.map((d) => d.revenue));\n    const orders = sum(rows.map((d) => d.orders));\n    const sessions = sum(rows.map((d) => d.sessions));\n    return { revenue, orders, aov: revenue / orders, conversion: (orders / sessions) * 100 };\n  };\n  const now = total(current);\n  const before = total(previous);\n  // Channel shares shift a little with the range; the last one takes the rounding remainder.\n  const shares = range === '7d' ? [0.46, 0.24, 0.16, 0.09] : range === '30d' ? [0.44, 0.25, 0.17, 0.08] : [0.42, 0.26, 0.18, 0.08];\n  const names = ['Online store', 'Subscriptions', 'Wholesale', 'Marketplace', 'Pop-up shops'];\n  const parts = shares.map((s) => Math.round(now.revenue * s));\n  const channels = names.map((name, i) => ({ name, value: i < parts.length ? parts[i] : now.revenue - sum(parts) }));\n  return {\n    days: n,\n    current,\n    previous,\n    from: dayLabel(current[0].date),\n    to: `${dayLabel(current[n - 1].date)}, 2026`,\n    channels,\n    kpis: [\n      { id: 'revenue', label: 'Revenue', value: money(now.revenue), delta: change(now.revenue, before.revenue), unit: '%', spark: current.map((d) => d.revenue) },\n      { id: 'orders', label: 'Orders', value: now.orders.toLocaleString('en-US'), delta: change(now.orders, before.orders), unit: '%', spark: current.map((d) => d.orders) },\n      { id: 'aov', label: 'Average order', value: money2(now.aov), delta: change(now.aov, before.aov), unit: '%', spark: current.map((d) => d.revenue / d.orders) },\n      { id: 'conversion', label: 'Conversion', value: `${now.conversion.toFixed(2)}%`, delta: now.conversion - before.conversion, unit: ' pt', spark: current.map((d) => (d.orders / d.sessions) * 100) },\n    ],\n  };\n}\n\n// ---------------------------------------------------------------- Orders\nexport type OrderStatus = 'Paid' | 'Pending' | 'Refunded' | 'Failed';\nexport type Line = { name: string; qty: number; price: number };\nexport type Order = {\n  id: string;\n  customer: string;\n  email: string;\n  date: number;\n  channel: string;\n  status: OrderStatus;\n  lines: Line[];\n  total: number;\n};\n\nexport const STATUS_COLOR = { Paid: 'success', Pending: 'warning', Refunded: 'neutral', Failed: 'danger' } as const;\n\nconst PRODUCTS: [string, number][] = [\n  ['Jasmine Pearls, 100 g', 18],\n  ['Earl Grey Reserve, 250 g', 24],\n  ['Sencha Fukamushi, 100 g', 21],\n  ['Masala Chai Blend, 250 g', 16],\n  ['Glass Teapot, 600 ml', 34],\n  ['Matcha Starter Kit', 48],\n  ['Oolong Sampler, 6 teas', 29],\n  ['Cast-iron Kettle', 72],\n];\n\nconst PEOPLE = [\n  'Ines Castillo', 'Tomas Lindqvist', 'Priya Raman', 'Dara Okonkwo', 'Jun Takeda', 'Mirela Popa',\n  'Callum Reyes', 'Noor Haddad', 'Sofia Brandt', 'Elio Marchetti', 'Wren Abara', 'Hana Kovac',\n  'Luca Ferrand', 'Amara Diallo', 'Theo Vance', 'Yuki Morimoto',\n];\nexport const emailFor = (name: string) => `${name.toLowerCase().replace(/[^a-z]+/g, '.')}@example.com`;\nexport const initials = (name: string) => name.split(/\\s+/).filter(Boolean).slice(0, 2).map((p) => p[0].toUpperCase()).join('');\n\nexport const ORDERS: Order[] = (() => {\n  const rand = seeded(42);\n  const pick = <T,>(list: readonly T[]) => list[Math.floor(rand() * list.length)];\n  const channels = ['Online store', 'Online store', 'Online store', 'Subscriptions', 'Wholesale', 'Marketplace'];\n  return Array.from({ length: 48 }, (_, i) => {\n    const lines: Line[] = [];\n    const count = 1 + Math.floor(rand() * 3);\n    while (lines.length < count) {\n      const [name, price] = pick(PRODUCTS);\n      if (!lines.some((l) => l.name === name)) lines.push({ name, price, qty: 1 + Math.floor(rand() * 2.4) });\n    }\n    const roll = rand();\n    const status: OrderStatus = i < 6 && roll < 0.5 ? 'Pending' : roll < 0.78 ? 'Paid' : roll < 0.88 ? 'Pending' : roll < 0.95 ? 'Refunded' : 'Failed';\n    const customer = pick(PEOPLE);\n    return {\n      id: `MT-${3184 - i}`,\n      customer,\n      email: emailFor(customer),\n      date: TODAY - Math.floor(i / 4) * DAY,\n      channel: pick(channels),\n      status,\n      lines,\n      total: sum(lines.map((l) => l.price * l.qty)),\n    };\n  });\n})();\n\n// ---------------------------------------------------------------- Customers\nexport type Customer = { name: string; email: string; city: string; since: string; tier: 'Member' | 'Regular' | 'New' };\nconst CITIES = ['Lisbon', 'Malmö', 'Chennai', 'Lagos', 'Osaka', 'Cluj', 'Austin', 'Amman', 'Hamburg', 'Turin', 'Accra', 'Zagreb', 'Lyon', 'Dakar', 'Leeds', 'Kyoto'];\nexport const CUSTOMERS: Customer[] = PEOPLE.map((name, i) => ({\n  name,\n  email: emailFor(name),\n  city: CITIES[i],\n  since: `${MONTHS[(i * 5) % 12]} ${2022 + (i % 4)}`,\n  tier: i % 3 === 0 ? 'Member' : i % 3 === 1 ? 'Regular' : 'New',\n}));\n\n// ---------------------------------------------------------------- Activity\nexport const ACTIVITY = [\n  { who: 'Priya Raman', what: 'started a monthly subscription', when: '12 min ago', tone: 'success' },\n  { who: 'Stock alert', what: 'Matcha Starter Kit is down to 8 units', when: '41 min ago', tone: 'warning' },\n  { who: 'Jun Takeda', what: 'left a 5-star review on Sencha Fukamushi', when: '2 h ago', tone: 'info' },\n  { who: 'Payout', what: '$4,812.40 sent to your bank account', when: '5 h ago', tone: 'success' },\n  { who: 'Callum Reyes', what: 'asked for a refund on a damaged teapot', when: 'Yesterday', tone: 'danger' },\n] as const;\n"}],
  "inbox": [{"file":"index.tsx","source":"'use client';\n// Inbox: a three-pane mail client for \"Juniper Studio\" (fictional).\n// Folders | message list | reading pane. Sample mail lives in ./data.ts. The layout\n// follows the width of its container, not the viewport:\n//   >= 1100px  folders, list and reading pane side by side\n//   >=  760px  list and reading pane; folders open in a drawer\n//   narrower   the list, then the message full width with a back button\nimport * as React from 'react';\nimport { Box, ButtonBase, DialogActions, DialogContent, DialogTitle, Divider, IconButton, Stack, Typography } from '@mui/material';\nimport InboxOutlined from '@mui/icons-material/InboxOutlined';\nimport StarBorder from '@mui/icons-material/StarBorder';\nimport Star from '@mui/icons-material/Star';\nimport SendOutlined from '@mui/icons-material/SendOutlined';\nimport DraftsOutlined from '@mui/icons-material/DraftsOutlined';\nimport ArchiveOutlined from '@mui/icons-material/ArchiveOutlined';\nimport DeleteOutlined from '@mui/icons-material/DeleteOutlined';\nimport MarkEmailUnreadOutlined from '@mui/icons-material/MarkEmailUnreadOutlined';\nimport ArrowBack from '@mui/icons-material/ArrowBack';\nimport MenuIcon from '@mui/icons-material/Menu';\nimport Close from '@mui/icons-material/Close';\nimport Search from '@mui/icons-material/Search';\nimport EditOutlined from '@mui/icons-material/EditOutlined';\nimport AttachFile from '@mui/icons-material/AttachFile';\nimport Reply from '@mui/icons-material/Reply';\nimport MarkunreadMailboxOutlined from '@mui/icons-material/MarkunreadMailboxOutlined';\nimport { Avatar, Button, Chip, Dialog, Drawer, Snackbar, Tabs, TextField, Tooltip } from '@sorbet-ui/react';\nimport { colorPalette } from '@sorbet-ui/tokens';\nimport { LABEL_COLOR, ME, MESSAGES, initials, type Accent, type FolderId, type Label, type Message } from './data';\n\nconst CQ = { md: '@container (min-width: 760px)', lg: '@container (min-width: 1100px)' } as const;\nconst TAP = { '@media (pointer: coarse)': { minHeight: 44, minWidth: 44 } } as const;\n\nconst FOLDERS: { id: FolderId; label: string; icon: React.ReactNode }[] = [\n  { id: 'inbox', label: 'Inbox', icon: <InboxOutlined fontSize=\"small\" /> },\n  { id: 'starred', label: 'Starred', icon: <StarBorder fontSize=\"small\" /> },\n  { id: 'sent', label: 'Sent', icon: <SendOutlined fontSize=\"small\" /> },\n  { id: 'drafts', label: 'Drafts', icon: <DraftsOutlined fontSize=\"small\" /> },\n  { id: 'archive', label: 'Archive', icon: <ArchiveOutlined fontSize=\"small\" /> },\n  { id: 'trash', label: 'Trash', icon: <DeleteOutlined fontSize=\"small\" /> },\n];\nconst LABELS = Object.keys(LABEL_COLOR) as Label[];\ntype Filter = 'all' | 'unread' | 'starred';\n\nconst inFolder = (m: Message, f: FolderId) => (f === 'starred' ? m.starred && m.folder !== 'trash' : m.folder === f);\n\nexport default function Inbox({ accent = 'secondary' }: { accent?: Accent }) {\n  const [mail, setMail] = React.useState<Message[]>(MESSAGES);\n  const [folder, setFolder] = React.useState<FolderId>('inbox');\n  const [label, setLabel] = React.useState<Label | null>(null);\n  const [filter, setFilter] = React.useState<Filter>('all');\n  const [query, setQuery] = React.useState('');\n  const [openId, setOpenId] = React.useState<string | null>('m1');\n  // Narrow containers show one pane at a time: the list, or the open message.\n  const [reading, setReading] = React.useState(false);\n  const [navOpen, setNavOpen] = React.useState(false);\n  const [composeOpen, setComposeOpen] = React.useState(false);\n  const [draft, setDraft] = React.useState({ to: '', subject: '', body: '' });\n  const [reply, setReply] = React.useState('');\n  const [toast, setToast] = React.useState<{ id: number; message: string; open: boolean } | null>(null);\n  const notify = (message: string) => setToast((t) => ({ id: (t?.id ?? 0) + 1, message, open: true }));\n  const listHeading = React.useRef<HTMLHeadingElement>(null);\n  const readHeading = React.useRef<HTMLHeadingElement>(null);\n  const composeTitle = React.useId();\n\n  const needle = query.trim().toLowerCase();\n  const list = mail.filter(\n    (m) =>\n      inFolder(m, folder) &&\n      (!label || m.labels.includes(label)) &&\n      (filter === 'all' || (filter === 'unread' ? m.unread : m.starred)) &&\n      `${m.from} ${m.email} ${m.subject} ${m.body.join(' ')}`.toLowerCase().includes(needle),\n  );\n  const open = mail.find((m) => m.id === openId) ?? null;\n  const unreadIn = (f: FolderId) => mail.filter((m) => inFolder(m, f) && m.unread).length;\n  const unreadHere = mail.filter((m) => inFolder(m, folder) && (!label || m.labels.includes(label)) && m.unread).length;\n  const title = label ?? FOLDERS.find((f) => f.id === folder)!.label;\n\n  const update = (id: string, patch: Partial<Message>) => setMail((all) => all.map((m) => (m.id === id ? { ...m, ...patch } : m)));\n\n  const choose = (m: Message) => {\n    setOpenId(m.id);\n    setReply('');\n    if (m.unread) update(m.id, { unread: false });\n    setReading(true);\n    // On narrow containers the reading pane replaces the list: move focus to it.\n    requestAnimationFrame(() => readHeading.current?.focus({ preventScroll: true }));\n  };\n\n  const goFolder = (f: FolderId, l: Label | null = null) => {\n    setFolder(f);\n    setLabel(l);\n    setFilter('all');\n    setReading(false);\n    setNavOpen(false);\n    requestAnimationFrame(() => listHeading.current?.focus({ preventScroll: true }));\n  };\n\n  // Moving a message out of the current view opens the next one in the list.\n  const moveTo = (m: Message, target: Message['folder'], message: string) => {\n    const i = list.findIndex((x) => x.id === m.id);\n    const next = list[i + 1] ?? list[i - 1] ?? null;\n    update(m.id, { folder: target });\n    setOpenId(next && next.id !== m.id ? next.id : null);\n    if (!next) setReading(false);\n    notify(message);\n  };\n\n  const sendReply = () => {\n    const body = reply.trim();\n    if (!open || !body) return;\n    update(open.id, { replies: [...(open.replies ?? []), { from: ME.name, time: 'Just now', body }] });\n    setReply('');\n    notify(`Reply sent to ${open.from}`);\n  };\n\n  const sendNew = () => {\n    if (!draft.to.trim() || !draft.subject.trim()) return;\n    const id = `n${Date.now()}`;\n    setMail((all) => [\n      { id, folder: 'sent', to: draft.to.trim(), from: ME.name, email: ME.email, subject: draft.subject.trim(), body: [draft.body.trim() || '(No message)'], time: 'Now', date: 'Just now', unread: false, starred: false, labels: [] },\n      ...all,\n    ]);\n    setComposeOpen(false);\n    notify(`Message sent to ${draft.to.trim()}`);\n  };\n\n  const navItem = (key: string, on: boolean, onClick: () => void, icon: React.ReactNode, text: string, count?: number) => (\n    <ButtonBase\n      key={key}\n      onClick={onClick}\n      aria-current={on ? 'page' : undefined}\n      sx={{\n        justifyContent: 'flex-start',\n        gap: 1.5,\n        px: 1.5,\n        minHeight: 38,\n        borderRadius: '10px',\n        fontSize: 14,\n        fontWeight: on ? 700 : 500,\n        color: on ? 'text.primary' : 'text.secondary',\n        bgcolor: on ? 'action.selected' : 'transparent',\n        '&:hover': { bgcolor: 'action.hover', color: 'text.primary' },\n        '&:focus-visible': { outline: '2px solid', outlineColor: colorPalette[accent][500], outlineOffset: -2 },\n        ...TAP,\n      }}\n    >\n      {icon}\n      <Box component=\"span\" sx={{ flex: 1, textAlign: 'left' }}>\n        {text}\n      </Box>\n      {!!count && (\n        <Box component=\"span\" aria-label={`${count} unread`} sx={{ fontSize: 12, fontWeight: 700, fontVariantNumeric: 'tabular-nums' }}>\n          {count}\n        </Box>\n      )}\n    </ButtonBase>\n  );\n\n  const folders = (\n    <Stack spacing={2} sx={{ p: 1.5 }}>\n      <Button\n        color={accent}\n        startIcon={<EditOutlined />}\n        onClick={() => {\n          setDraft({ to: '', subject: '', body: '' });\n          setNavOpen(false);\n          setComposeOpen(true);\n        }}\n      >\n        Compose\n      </Button>\n      <Box component=\"nav\" aria-label=\"Folders\" sx={{ display: 'grid', gap: 0.25 }}>\n        {FOLDERS.map((f) => navItem(f.id, folder === f.id && !label, () => goFolder(f.id), f.icon, f.label, f.id === 'inbox' || f.id === 'starred' ? unreadIn(f.id) : undefined))}\n      </Box>\n      <Box>\n        <Typography id=\"inbox-labels\" sx={{ px: 1.5, pb: 0.5, fontSize: 12, fontWeight: 700, color: 'text.secondary', textTransform: 'uppercase', letterSpacing: '.06em' }}>\n          Labels\n        </Typography>\n        <Box role=\"group\" aria-labelledby=\"inbox-labels\" sx={{ display: 'grid', gap: 0.25 }}>\n          {LABELS.map((l) =>\n            navItem(l, label === l, () => goFolder('inbox', l), <Box aria-hidden sx={{ width: 10, height: 10, mx: '5px', borderRadius: '50%', bgcolor: colorPalette[LABEL_COLOR[l]][500] }} />, l),\n          )}\n        </Box>\n      </Box>\n    </Stack>\n  );\n\n  // ---------------------------------------------------------------- List pane\n  const listPane = (\n    <Box\n      component=\"section\"\n      aria-labelledby=\"inbox-list-title\"\n      sx={{\n        display: reading ? 'none' : 'flex',\n        flexDirection: 'column',\n        minWidth: 0,\n        flex: 1,\n        bgcolor: 'background.paper',\n        [CQ.md]: { display: 'flex', flex: '0 0 340px', borderRight: 1, borderColor: 'divider' },\n        [CQ.lg]: { flexBasis: 380 },\n      }}\n    >\n      <Box sx={{ p: 2, pb: 1.5, display: 'grid', gap: 1.5 }}>\n        <Stack direction=\"row\" spacing={1} sx={{ alignItems: 'center' }}>\n          <IconButton aria-label=\"Open folders\" aria-expanded={navOpen} onClick={() => setNavOpen(true)} edge=\"start\" sx={{ [CQ.lg]: { display: 'none' }, ...TAP }}>\n            <MenuIcon />\n          </IconButton>\n          <Typography ref={listHeading} id=\"inbox-list-title\" component=\"h2\" tabIndex={-1} sx={{ flex: 1, fontWeight: 800, fontSize: 20, letterSpacing: '-0.02em', outline: 'none' }}>\n            {title}\n          </Typography>\n          <Typography sx={{ fontSize: 13, color: 'text.secondary' }}>{list.length} {list.length === 1 ? 'message' : 'messages'}</Typography>\n        </Stack>\n        <TextField\n          size=\"sm\"\n          variant=\"outlined\"\n          color={accent}\n          placeholder=\"Search mail\"\n          value={query}\n          onChange={(e) => setQuery(e.target.value)}\n          startIcon={<Search fontSize=\"small\" />}\n          slotProps={{ htmlInput: { 'aria-label': 'Search mail' } }}\n          fullWidth\n        />\n        <Tabs\n          size=\"sm\"\n          variant=\"soft\"\n          color={accent}\n          value={filter}\n          onChange={(id) => setFilter(id as Filter)}\n          renderPanels={false}\n          aria-label=\"Show\"\n          tabs={[\n            { id: 'all', label: 'All' },\n            { id: 'unread', label: `Unread (${unreadHere})` },\n            { id: 'starred', label: 'Starred' },\n          ]}\n        />\n      </Box>\n      <Divider />\n      <Box sx={{ flex: 1, minHeight: 0, overflowY: 'auto' }}>\n        {list.length === 0 ? (\n          <Stack spacing={1} sx={{ alignItems: 'center', textAlign: 'center', px: 3, py: 6 }}>\n            <MarkunreadMailboxOutlined sx={{ fontSize: 36, color: 'text.secondary' }} />\n            <Typography sx={{ fontWeight: 700 }}>{needle ? 'No messages match' : 'Nothing here'}</Typography>\n            <Typography variant=\"body2\" color=\"text.secondary\">\n              {needle ? `Nothing in ${title} matches \"${query.trim()}\".` : filter === 'all' ? `${title} is empty.` : `No ${filter} messages in ${title}.`}\n            </Typography>\n            {(needle || filter !== 'all') && (\n              <Button size=\"sm\" variant=\"soft\" color={accent} onClick={() => { setQuery(''); setFilter('all'); }}>\n                Clear filters\n              </Button>\n            )}\n          </Stack>\n        ) : (\n          <Box component=\"ul\" aria-label={`${title} messages`} sx={{ listStyle: 'none', m: 0, p: 0 }}>\n            {list.map((m) => {\n              const on = m.id === openId;\n              return (\n                <Box component=\"li\" key={m.id} sx={{ position: 'relative', borderBottom: 1, borderColor: 'divider' }}>\n                  <ButtonBase\n                    onClick={() => choose(m)}\n                    aria-current={on ? 'true' : undefined}\n                    aria-label={`${m.unread ? 'Unread. ' : ''}${m.to ? `To ${m.to}` : m.from}: ${m.subject}. ${m.time}`}\n                    sx={{\n                      display: 'flex',\n                      alignItems: 'flex-start',\n                      gap: 1.5,\n                      width: '100%',\n                      textAlign: 'left',\n                      pl: 2,\n                      pr: 6,\n                      py: 1.5,\n                      bgcolor: on ? 'action.selected' : 'transparent',\n                      boxShadow: on ? `inset 3px 0 0 ${colorPalette[accent][500]}` : 'none',\n                      '&:hover': { bgcolor: on ? 'action.selected' : 'action.hover' },\n                      '&:focus-visible': { outline: '2px solid', outlineColor: colorPalette[accent][500], outlineOffset: -2 },\n                    }}\n                  >\n                    <Avatar size=\"sm\" variant=\"soft\" color={m.labels[0] ? LABEL_COLOR[m.labels[0]] : 'neutral'}>\n                      {initials(m.from)}\n                    </Avatar>\n                    <Box sx={{ minWidth: 0, flex: 1 }}>\n                      <Stack direction=\"row\" spacing={1} sx={{ alignItems: 'baseline' }}>\n                        <Typography noWrap sx={{ flex: 1, fontSize: 14, fontWeight: m.unread ? 800 : 600 }}>\n                          {m.to ? `To: ${m.to}` : m.from}\n                        </Typography>\n                        <Typography sx={{ fontSize: 12, color: m.unread ? 'text.primary' : 'text.secondary', fontWeight: m.unread ? 700 : 400, flexShrink: 0 }}>{m.time}</Typography>\n                      </Stack>\n                      <Typography noWrap sx={{ fontSize: 13, fontWeight: m.unread ? 700 : 500 }}>\n                        {m.subject}\n                      </Typography>\n                      <Typography sx={{ fontSize: 13, color: 'text.secondary', display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>{m.body[0]}</Typography>\n                      {(m.labels.length > 0 || m.attachments) && (\n                        <Stack direction=\"row\" sx={{ gap: 0.5, mt: 0.75, flexWrap: 'wrap', alignItems: 'center' }}>\n                          {m.labels.map((l) => (\n                            <Chip key={l} size=\"xs\" variant=\"soft\" color={LABEL_COLOR[l]} label={l} />\n                          ))}\n                          {m.attachments && <AttachFile aria-label={`${m.attachments.length} attachments`} sx={{ fontSize: 15, color: 'text.secondary' }} />}\n                        </Stack>\n                      )}\n                    </Box>\n                    {m.unread && <Box aria-hidden sx={{ position: 'absolute', left: 6, top: 26, width: 6, height: 6, borderRadius: '50%', bgcolor: colorPalette[accent][500] }} />}\n                  </ButtonBase>\n                  <IconButton\n                    size=\"small\"\n                    aria-label={m.starred ? `Unstar ${m.subject}` : `Star ${m.subject}`}\n                    aria-pressed={m.starred}\n                    onClick={() => update(m.id, { starred: !m.starred })}\n                    sx={{ position: 'absolute', right: 8, top: 34, color: m.starred ? colorPalette.warning[500] : 'text.secondary', ...TAP }}\n                  >\n                    {m.starred ? <Star fontSize=\"small\" /> : <StarBorder fontSize=\"small\" />}\n                  </IconButton>\n                </Box>\n              );\n            })}\n          </Box>\n        )}\n      </Box>\n    </Box>\n  );\n\n  // ---------------------------------------------------------------- Reading pane\n  const tool = (labelText: string, icon: React.ReactNode, onClick: () => void, pressed?: boolean) => (\n    <Tooltip title={labelText}>\n      <IconButton aria-label={labelText} aria-pressed={pressed} onClick={onClick} sx={TAP}>\n        {icon}\n      </IconButton>\n    </Tooltip>\n  );\n\n  const readingPane = (\n    <Box\n      component=\"section\"\n      aria-label=\"Message\"\n      sx={{ display: reading ? 'flex' : 'none', flexDirection: 'column', flex: 1, minWidth: 0, bgcolor: 'background.default', [CQ.md]: { display: 'flex' } }}\n    >\n      {open ? (\n        <>\n          <Stack direction=\"row\" spacing={0.5} sx={{ alignItems: 'center', px: 1, minHeight: 56, borderBottom: 1, borderColor: 'divider', bgcolor: 'background.paper', flexShrink: 0 }}>\n            <Box sx={{ [CQ.md]: { display: 'none' } }}>\n              <IconButton\n                aria-label={`Back to ${title}`}\n                onClick={() => {\n                  setReading(false);\n                  requestAnimationFrame(() => listHeading.current?.focus({ preventScroll: true }));\n                }}\n                sx={TAP}\n              >\n                <ArrowBack />\n              </IconButton>\n            </Box>\n            {open.folder !== 'archive' && tool('Archive', <ArchiveOutlined />, () => moveTo(open, 'archive', 'Conversation archived'))}\n            {open.folder !== 'trash' && tool('Delete', <DeleteOutlined />, () => moveTo(open, 'trash', 'Moved to Trash'))}\n            {tool('Mark as unread', <MarkEmailUnreadOutlined />, () => {\n              update(open.id, { unread: true });\n              setReading(false);\n              notify('Marked as unread');\n            })}\n            {tool(open.starred ? 'Unstar' : 'Star', open.starred ? <Star sx={{ color: colorPalette.warning[500] }} /> : <StarBorder />, () => update(open.id, { starred: !open.starred }), open.starred)}\n            <Box sx={{ flex: 1 }} />\n            <Typography sx={{ fontSize: 13, color: 'text.secondary', pr: 1, display: 'none', [CQ.md]: { display: 'block' } }}>{open.date}</Typography>\n          </Stack>\n          <Box sx={{ flex: 1, minHeight: 0, overflowY: 'auto', px: 2.5, py: 3, [CQ.lg]: { px: 5 } }}>\n            <Box sx={{ maxWidth: 720, mx: 'auto' }}>\n              <Typography ref={readHeading} component=\"h2\" tabIndex={-1} sx={{ fontWeight: 800, fontSize: 22, lineHeight: 1.25, letterSpacing: '-0.02em', outline: 'none' }}>\n                {open.subject}\n              </Typography>\n              {open.labels.length > 0 && (\n                <Stack direction=\"row\" sx={{ gap: 0.5, mt: 1, flexWrap: 'wrap' }}>\n                  {open.labels.map((l) => (\n                    <Chip key={l} size=\"sm\" variant=\"soft\" color={LABEL_COLOR[l]} label={l} />\n                  ))}\n                </Stack>\n              )}\n              <Stack direction=\"row\" spacing={1.5} sx={{ alignItems: 'center', mt: 2.5 }}>\n                <Avatar variant=\"soft\" color={open.labels[0] ? LABEL_COLOR[open.labels[0]] : 'neutral'}>\n                  {initials(open.from)}\n                </Avatar>\n                <Box sx={{ minWidth: 0, flex: 1 }}>\n                  <Typography noWrap sx={{ fontWeight: 700, fontSize: 15 }}>\n                    {open.from}\n                  </Typography>\n                  <Typography noWrap sx={{ fontSize: 13, color: 'text.secondary' }}>\n                    {open.email} · to {open.to ?? 'me'}\n                  </Typography>\n                </Box>\n              </Stack>\n              <Box sx={{ mt: 2.5, display: 'grid', gap: 1.5 }}>\n                {open.body.map((p, i) => (\n                  <Typography key={i} sx={{ fontSize: 15, lineHeight: 1.65 }}>\n                    {p}\n                  </Typography>\n                ))}\n              </Box>\n              {open.attachments && (\n                <Box sx={{ mt: 3 }}>\n                  <Typography component=\"h3\" sx={{ fontSize: 13, fontWeight: 700, color: 'text.secondary', mb: 1 }}>\n                    {open.attachments.length} {open.attachments.length === 1 ? 'attachment' : 'attachments'}\n                  </Typography>\n                  <Stack direction=\"row\" sx={{ gap: 1, flexWrap: 'wrap' }}>\n                    {open.attachments.map((a) => (\n                      <ButtonBase\n                        key={a.name}\n                        onClick={() => notify(`Downloading ${a.name}`)}\n                        aria-label={`Download ${a.name}, ${a.size}`}\n                        sx={{ gap: 1.25, px: 1.5, py: 1, borderRadius: '12px', border: 1, borderColor: 'divider', bgcolor: 'background.paper', textAlign: 'left', '&:hover': { borderColor: colorPalette[accent][500] }, '&:focus-visible': { outline: '2px solid', outlineColor: colorPalette[accent][500] } }}\n                      >\n                        <AttachFile fontSize=\"small\" sx={{ color: 'text.secondary' }} />\n                        <Box>\n                          <Typography sx={{ fontSize: 13, fontWeight: 600 }}>{a.name}</Typography>\n                          <Typography sx={{ fontSize: 12, color: 'text.secondary' }}>{a.size}</Typography>\n                        </Box>\n                      </ButtonBase>\n                    ))}\n                  </Stack>\n                </Box>\n              )}\n              {(open.replies ?? []).map((r, i) => (\n                <Box key={i} sx={{ mt: 3, p: 2, borderRadius: '14px', border: 1, borderColor: 'divider', bgcolor: 'background.paper' }}>\n                  <Stack direction=\"row\" spacing={1.25} sx={{ alignItems: 'center', mb: 1 }}>\n                    <Avatar size=\"xs\" variant=\"solid\" color={accent}>\n                      {initials(r.from)}\n                    </Avatar>\n                    <Typography sx={{ fontSize: 13, fontWeight: 700, flex: 1 }}>{r.from}</Typography>\n                    <Typography sx={{ fontSize: 12, color: 'text.secondary' }}>{r.time}</Typography>\n                  </Stack>\n                  <Typography sx={{ fontSize: 14, lineHeight: 1.6 }}>{r.body}</Typography>\n                </Box>\n              ))}\n              {open.folder !== 'sent' && open.folder !== 'drafts' && (\n                <Box component=\"form\" noValidate onSubmit={(e: React.FormEvent) => { e.preventDefault(); sendReply(); }} sx={{ mt: 3, p: 2, borderRadius: '14px', border: 1, borderColor: 'divider', bgcolor: 'background.paper' }}>\n                  <TextField\n                    label={`Reply to ${open.from}`}\n                    color={accent}\n                    multiline\n                    minRows={3}\n                    fullWidth\n                    value={reply}\n                    onChange={(e) => setReply(e.target.value)}\n                    onKeyDown={(e) => {\n                      if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) sendReply();\n                    }}\n                  />\n                  <Stack direction=\"row\" sx={{ mt: 1.5, alignItems: 'center', justifyContent: 'space-between', gap: 1 }}>\n                    <Typography sx={{ fontSize: 12, color: 'text.secondary' }}>Ctrl + Enter to send</Typography>\n                    <Button type=\"submit\" color={accent} startIcon={<Reply />} disabled={!reply.trim()}>\n                      Send reply\n                    </Button>\n                  </Stack>\n                </Box>\n              )}\n            </Box>\n          </Box>\n        </>\n      ) : (\n        <Stack spacing={1} sx={{ flex: 1, alignItems: 'center', justifyContent: 'center', textAlign: 'center', p: 4 }}>\n          <InboxOutlined sx={{ fontSize: 40, color: 'text.secondary' }} />\n          <Typography component=\"h2\" sx={{ fontWeight: 700 }}>\n            No message selected\n          </Typography>\n          <Typography variant=\"body2\" color=\"text.secondary\">\n            Choose a message from the list to read it here.\n          </Typography>\n        </Stack>\n      )}\n    </Box>\n  );\n\n  return (\n    <Box sx={{ containerType: 'inline-size', height: '100%', minHeight: 560, bgcolor: 'background.default', color: 'text.primary' }}>\n      <Box sx={{ display: 'flex', height: '100%' }}>\n        <Box component=\"aside\" aria-label=\"Mailbox\" sx={{ display: 'none', [CQ.lg]: { display: 'flex' }, flexDirection: 'column', width: 236, flexShrink: 0, borderRight: 1, borderColor: 'divider', bgcolor: 'background.paper' }}>\n          <Brand accent={accent} />\n          <Divider />\n          {folders}\n        </Box>\n        {listPane}\n        {readingPane}\n      </Box>\n\n      <Drawer open={navOpen} onClose={() => setNavOpen(false)} anchor=\"left\" aria-label=\"Mailbox\">\n        <Box sx={{ width: 264 }}>\n          <Stack direction=\"row\" sx={{ alignItems: 'center', justifyContent: 'space-between', pr: 1 }}>\n            <Brand accent={accent} />\n            <IconButton aria-label=\"Close folders\" onClick={() => setNavOpen(false)} sx={TAP}>\n              <Close />\n            </IconButton>\n          </Stack>\n          <Divider />\n          {folders}\n        </Box>\n      </Drawer>\n\n      <Dialog open={composeOpen} onClose={() => setComposeOpen(false)} maxWidth=\"sm\" fullWidth aria-labelledby={composeTitle}>\n        <DialogTitle id={composeTitle}>New message</DialogTitle>\n        <Box component=\"form\" noValidate sx={{ display: 'contents' }} onSubmit={(e: React.FormEvent) => { e.preventDefault(); sendNew(); }}>\n          <DialogContent>\n            <Stack spacing={2} sx={{ pt: 1 }}>\n              <TextField label=\"To\" type=\"email\" color={accent} value={draft.to} onChange={(e) => setDraft((d) => ({ ...d, to: e.target.value }))} fullWidth autoFocus placeholder=\"name@company.example\" />\n              <TextField label=\"Subject\" color={accent} value={draft.subject} onChange={(e) => setDraft((d) => ({ ...d, subject: e.target.value }))} fullWidth />\n              <TextField label=\"Message\" color={accent} value={draft.body} onChange={(e) => setDraft((d) => ({ ...d, body: e.target.value }))} fullWidth multiline minRows={5} />\n            </Stack>\n          </DialogContent>\n          <DialogActions>\n            <Button variant=\"ghost\" color=\"neutral\" onClick={() => setComposeOpen(false)}>\n              Discard\n            </Button>\n            <Button type=\"submit\" color={accent} startIcon={<SendOutlined />} disabled={!draft.to.trim() || !draft.subject.trim()}>\n              Send\n            </Button>\n          </DialogActions>\n        </Box>\n      </Dialog>\n\n      <Snackbar\n        key={toast?.id ?? 0}\n        open={toast?.open ?? false}\n        autoHideDuration={3000}\n        onClose={(_, reason) => {\n          if (reason !== 'clickaway') setToast((t) => (t ? { ...t, open: false } : t));\n        }}\n        message={toast?.message ?? ''}\n        color=\"success\"\n        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}\n      />\n    </Box>\n  );\n}\n\nfunction Brand({ accent }: { accent: Accent }) {\n  return (\n    <Stack direction=\"row\" spacing={1.25} sx={{ alignItems: 'center', px: 2.5, py: 2 }}>\n      <Box aria-hidden sx={{ width: 30, height: 30, borderRadius: '10px', display: 'grid', placeItems: 'center', bgcolor: colorPalette[accent][600] }}>\n        <svg width=\"16\" height=\"16\" viewBox=\"0 0 16 16\">\n          <path d=\"M2 4.5 8 9l6-4.5M2.5 3.5h11a1 1 0 0 1 1 1v7a1 1 0 0 1-1 1h-11a1 1 0 0 1-1-1v-7a1 1 0 0 1 1-1Z\" fill=\"none\" stroke=\"#fff\" strokeWidth=\"1.6\" strokeLinejoin=\"round\" />\n        </svg>\n      </Box>\n      <Box>\n        <Typography sx={{ fontWeight: 800, fontSize: 15, lineHeight: 1.2 }}>Juniper Mail</Typography>\n        <Typography sx={{ fontSize: 12, color: 'text.secondary', lineHeight: 1.2 }}>{ME.email}</Typography>\n      </Box>\n    </Stack>\n  );\n}\n"},{"file":"data.ts","source":"// Sample mailbox for Maya Okafor at Juniper Studio (a fictional design studio).\n// People, companies and addresses are made up; every address ends in .example.\n\nexport type Accent = 'primary' | 'secondary' | 'success' | 'warning' | 'danger' | 'info';\nexport type FolderId = 'inbox' | 'starred' | 'sent' | 'drafts' | 'archive' | 'trash';\nexport type Label = 'Clients' | 'Team' | 'Finance' | 'Travel';\n\nexport type Reply = { from: string; time: string; body: string };\nexport type Message = {\n  id: string;\n  folder: Exclude<FolderId, 'starred'>;\n  from: string;\n  email: string;\n  subject: string;\n  /** Paragraphs. The first one doubles as the preview line in the list. */\n  body: string[];\n  /** Short label for the list (\"9:42 AM\", \"Tue\"). */\n  time: string;\n  /** Long form for the reading pane. */\n  date: string;\n  unread: boolean;\n  starred: boolean;\n  labels: Label[];\n  /** Recipient, for sent mail and drafts. */\n  to?: string;\n  attachments?: { name: string; size: string }[];\n  replies?: Reply[];\n};\n\nexport const ME = { name: 'Maya Okafor', email: 'maya@juniperstudio.example' };\n\nexport const LABEL_COLOR = { Clients: 'primary', Team: 'success', Finance: 'warning', Travel: 'secondary' } as const;\n\nexport const initials = (name: string) => name.split(/\\s+/).filter(Boolean).slice(0, 2).map((p) => p[0].toUpperCase()).join('');\n\nexport const MESSAGES: Message[] = [\n  {\n    id: 'm1',\n    folder: 'inbox',\n    from: 'Tomas Lindqvist',\n    email: 'tomas@harborcoffee.example',\n    subject: 'Feedback on the packaging concepts',\n    body: [\n      'Hi Maya, we went through the three packaging routes with the whole team this morning and there is a clear favorite.',\n      'Route B (the linocut illustrations) got the strongest reaction. People liked that it still reads as Harbor from across a shop, and the two-color print keeps us inside the budget we discussed.',\n      'Two requests before we sign off: can we see the decaf bag in the darker green, and could the roast date move to the back panel? Our retail partners stack the bags upright and the front label gets covered by the shelf lip.',\n      'If you can turn those around by Thursday we can take it to the printer the same week.',\n    ],\n    time: '9:42 AM',\n    date: 'Today, 9:42 AM',\n    unread: true,\n    starred: true,\n    labels: ['Clients'],\n    attachments: [\n      { name: 'route-b-notes.pdf', size: '240 KB' },\n      { name: 'shelf-photo.jpg', size: '1.8 MB' },\n    ],\n  },\n  {\n    id: 'm2',\n    folder: 'inbox',\n    from: 'Priya Raman',\n    email: 'priya@juniperstudio.example',\n    subject: 'Studio day: Friday the 20th?',\n    body: [\n      'Quick poll for the studio day. Friday the 20th works for the print workshop, and they can take all six of us.',\n      'It starts at 10 and runs to about 3, lunch included. I need to confirm numbers by Wednesday, so reply with a yes or no when you can.',\n      'I will sort the train tickets once I know who is coming.',\n    ],\n    time: '8:15 AM',\n    date: 'Today, 8:15 AM',\n    unread: true,\n    starred: false,\n    labels: ['Team'],\n  },\n  {\n    id: 'm3',\n    folder: 'inbox',\n    from: 'Ledgerly',\n    email: 'billing@ledgerly.example',\n    subject: 'Invoice INV-2041 was paid',\n    body: [\n      'Good news: Harbor Coffee paid invoice INV-2041 for $4,800.00. The payment will reach your account in one to two business days.',\n      'Invoice: INV-2041. Client: Harbor Coffee Roasters. Paid: November 10. Method: bank transfer.',\n      'You have 2 other invoices outstanding, totalling $6,150.00.',\n    ],\n    time: 'Yesterday',\n    date: 'Yesterday, 4:03 PM',\n    unread: true,\n    starred: false,\n    labels: ['Finance'],\n    attachments: [{ name: 'INV-2041-receipt.pdf', size: '86 KB' }],\n  },\n  {\n    id: 'm4',\n    folder: 'inbox',\n    from: 'Dara Okonkwo',\n    email: 'dara@fieldnotes.example',\n    subject: 'Re: Annual report timeline',\n    body: [\n      'Thanks for the revised schedule. Moving the photo shoot a week earlier works on our side.',\n      'The only fixed date is the board meeting on December 9: they need printed copies in the room, so files have to be with the printer by the 1st at the latest.',\n      'I have asked finance to send the final figures by next Friday so the charts are not a last-minute job this year.',\n    ],\n    time: 'Yesterday',\n    date: 'Yesterday, 11:27 AM',\n    unread: false,\n    starred: true,\n    labels: ['Clients'],\n    replies: [{ from: ME.name, time: 'Yesterday, 1:10 PM', body: 'Perfect. I will lock the shoot for the 18th and send a call sheet tomorrow.' }],\n  },\n  {\n    id: 'm5',\n    folder: 'inbox',\n    from: 'Skyline Rail',\n    email: 'tickets@skylinerail.example',\n    subject: 'Your tickets to Rotterdam, November 24',\n    body: [\n      'Your booking is confirmed. Two seats, coach 7, departing 07:52 and arriving 10:14.',\n      'Tickets are attached and also available in the app. Seat reservations can be changed free of charge until the day before travel.',\n    ],\n    time: 'Mon',\n    date: 'Monday, 6:48 PM',\n    unread: false,\n    starred: false,\n    labels: ['Travel'],\n    attachments: [{ name: 'tickets-RTM-2411.pdf', size: '312 KB' }],\n  },\n  {\n    id: 'm6',\n    folder: 'inbox',\n    from: 'Jun Takeda',\n    email: 'jun@juniperstudio.example',\n    subject: 'Type licence for the Fieldnotes job',\n    body: [\n      'The foundry got back to me. A web and print licence for the full family is $640 for up to five users, or $380 if we only take the four weights we are actually using.',\n      'I would take the four weights. Want me to go ahead and put it on the studio card?',\n    ],\n    time: 'Mon',\n    date: 'Monday, 2:20 PM',\n    unread: false,\n    starred: false,\n    labels: ['Team', 'Finance'],\n  },\n  {\n    id: 'm7',\n    folder: 'inbox',\n    from: 'Mirela Popa',\n    email: 'mirela@osterbakery.example',\n    subject: 'Signage is up!',\n    body: [\n      'The new sign went up on Saturday and we have already had three people come in just to say they like it. Photos attached.',\n      'Thank you for pushing us on the hand-painted version. It was the right call.',\n    ],\n    time: 'Sun',\n    date: 'Sunday, 9:05 AM',\n    unread: false,\n    starred: true,\n    labels: ['Clients'],\n    attachments: [\n      { name: 'oster-front.jpg', size: '2.4 MB' },\n      { name: 'oster-night.jpg', size: '2.1 MB' },\n    ],\n  },\n  {\n    id: 'm8',\n    folder: 'inbox',\n    from: 'Callum Reyes',\n    email: 'callum@juniperstudio.example',\n    subject: 'Portfolio review notes',\n    body: [\n      'Notes from yesterday, as promised. Short version: lead with the Oster Bakery identity, cut the two oldest case studies, and add process shots to Harbor.',\n      'I can pair with you on the case study copy on Thursday afternoon if that helps.',\n    ],\n    time: 'Nov 7',\n    date: 'November 7, 3:44 PM',\n    unread: false,\n    starred: false,\n    labels: ['Team'],\n  },\n  {\n    id: 'm9',\n    folder: 'inbox',\n    from: 'Ledgerly',\n    email: 'billing@ledgerly.example',\n    subject: 'Reminder: INV-2038 is 7 days overdue',\n    body: [\n      'Invoice INV-2038 to Fieldnotes Foundation for $3,400.00 was due on November 1 and has not been paid yet.',\n      'You can send a reminder from your dashboard, or mark the invoice as paid if the money has already arrived.',\n    ],\n    time: 'Nov 8',\n    date: 'November 8, 8:00 AM',\n    unread: false,\n    starred: false,\n    labels: ['Finance'],\n  },\n  {\n    id: 's1',\n    folder: 'sent',\n    to: 'Dara Okonkwo',\n    from: ME.name,\n    email: ME.email,\n    subject: 'Call sheet for the 18th',\n    body: [\n      'Hi Dara, call sheet attached for the shoot on the 18th. We start at the riverside site at 8:30 for the morning light and move indoors after lunch.',\n      'Let me know if any of the people on the list have changed.',\n    ],\n    time: 'Tue',\n    date: 'Tuesday, 10:02 AM',\n    unread: false,\n    starred: false,\n    labels: ['Clients'],\n    attachments: [{ name: 'call-sheet-nov-18.pdf', size: '128 KB' }],\n  },\n  {\n    id: 's2',\n    folder: 'sent',\n    to: 'Mirela Popa',\n    from: ME.name,\n    email: ME.email,\n    subject: 'Estimate: Oster Bakery winter menu',\n    body: ['Hi Mirela, here is the estimate for the winter menu boards and the takeaway cards. It covers two rounds of changes and print-ready files.'],\n    time: 'Nov 6',\n    date: 'November 6, 4:30 PM',\n    unread: false,\n    starred: false,\n    labels: ['Clients', 'Finance'],\n  },\n  {\n    id: 'd1',\n    folder: 'drafts',\n    to: 'Studio team',\n    from: ME.name,\n    email: ME.email,\n    subject: 'Studio rates for next year',\n    body: ['Team, before we send the January letters I would like us to agree on the new day rate. My proposal is below.'],\n    time: 'Nov 5',\n    date: 'November 5, 5:12 PM',\n    unread: false,\n    starred: false,\n    labels: ['Team'],\n  },\n  {\n    id: 'a1',\n    folder: 'archive',\n    from: 'Noor Haddad',\n    email: 'noor@lanternbooks.example',\n    subject: 'Cover files received, thank you',\n    body: ['All three covers arrived and the printer has confirmed the spine widths. We will send printed copies as soon as they are in.'],\n    time: 'Oct 29',\n    date: 'October 29, 12:18 PM',\n    unread: false,\n    starred: false,\n    labels: ['Clients'],\n  },\n];\n"}],
  "kanban": [{"file":"index.tsx","source":"'use client';\n// Kanban board: \"Pollen\", a fictional team's sprint. Four columns with WIP limits,\n// cards you can drag (motion/react, no drag-and-drop library) or move from a menu,\n// a card dialog with assignee, labels, due date and a checklist, inline \"add card\",\n// and a person filter. Every move is announced in a live region. Sample data in\n// ./data.ts. The board responds to its container: columns sit side by side when\n// there is room and scroll sideways (with snap points) when there is not.\nimport * as React from 'react';\nimport { Box, ButtonBase, DialogActions, DialogContent, DialogTitle, IconButton, Stack, Typography } from '@mui/material';\nimport Add from '@mui/icons-material/Add';\nimport MoreHoriz from '@mui/icons-material/MoreHoriz';\nimport DragIndicator from '@mui/icons-material/DragIndicator';\nimport CheckBoxOutlined from '@mui/icons-material/CheckBoxOutlined';\nimport EventOutlined from '@mui/icons-material/EventOutlined';\nimport NotesOutlined from '@mui/icons-material/NotesOutlined';\nimport Close from '@mui/icons-material/Close';\nimport DeleteOutlined from '@mui/icons-material/DeleteOutlined';\nimport { motion, MotionConfig, useDragControls, useReducedMotion } from 'motion/react';\nimport { Avatar, Button, Checkbox, Chip, Dialog, Menu, MenuItem, Progress, Select, Snackbar, TextField, Tooltip } from '@sorbet-ui/react';\nimport { colorPalette } from '@sorbet-ui/tokens';\nimport { COLUMNS, LABEL_COLOR, PEOPLE, TASKS, daysLeft, initials, personById, shortDate, type Accent, type ColumnId, type LabelId, type Task } from './data';\n\nconst CQ = { md: '@container (min-width: 760px)', lg: '@container (min-width: 1180px)' } as const;\nconst TAP = { '@media (pointer: coarse)': { minHeight: 44, minWidth: 44 } } as const;\nconst SR_ONLY = { position: 'absolute', width: '1px', height: '1px', overflow: 'hidden', clip: 'rect(0 0 0 0)', whiteSpace: 'nowrap' } as const;\nconst LABELS = Object.keys(LABEL_COLOR) as LabelId[];\nconst columnTitle = (id: ColumnId) => COLUMNS.find((c) => c.id === id)!.title;\n\nfunction DueChip({ due, done }: { due: string; done: boolean }) {\n  if (!due) return null;\n  const left = daysLeft(due);\n  const color = done ? 'neutral' : left < 0 ? 'danger' : left <= 2 ? 'warning' : 'neutral';\n  const when = done ? shortDate(due) : left < 0 ? `${shortDate(due)}, overdue` : left === 0 ? 'Today' : left === 1 ? 'Tomorrow' : shortDate(due);\n  return <Chip size=\"xs\" variant={color === 'neutral' ? 'outlined' : 'soft'} color={color} icon={<EventOutlined />} label={when} aria-label={`Due ${when}`} />;\n}\n\ntype CardProps = {\n  task: Task;\n  accent: Accent;\n  onOpen: (t: Task) => void;\n  onMove: (t: Task, to: ColumnId) => void;\n  onDrop: (t: Task, x: number, y: number) => void;\n  onHover: (x: number, y: number) => void;\n  onDragState: (dragging: boolean) => void;\n};\n\nfunction Card({ task, accent, onOpen, onMove, onDrop, onHover, onDragState }: CardProps) {\n  const controls = useDragControls();\n  const reduce = useReducedMotion();\n  const dragged = React.useRef(false);\n  const [menu, setMenu] = React.useState<HTMLElement | null>(null);\n  const person = personById(task.assignee);\n  const done = task.checklist.filter((c) => c.done).length;\n  return (\n    <motion.li\n      layout={!reduce}\n      layoutId={task.id}\n      drag\n      dragControls={controls}\n      dragListener={false}\n      dragSnapToOrigin\n      dragMomentum={false}\n      whileDrag={{ scale: 1.03, rotate: reduce ? 0 : 2, zIndex: 20, cursor: 'grabbing' }}\n      onDragStart={() => {\n        dragged.current = true;\n        onDragState(true);\n      }}\n      onDrag={(_, info) => onHover(info.point.x - window.scrollX, info.point.y - window.scrollY)}\n      onDragEnd={(_, info) => {\n        onDragState(false);\n        onDrop(task, info.point.x - window.scrollX, info.point.y - window.scrollY);\n        // The click that ends a drag must not open the card.\n        setTimeout(() => (dragged.current = false), 0);\n      }}\n      style={{ listStyle: 'none', position: 'relative' }}\n    >\n      <Box\n        onPointerDown={(e: React.PointerEvent) => {\n          // Mouse and pen drag from anywhere on the card; touch uses the handle so the board still scrolls.\n          if (e.pointerType !== 'touch' && !(e.target as HTMLElement).closest('[data-no-drag]')) controls.start(e);\n        }}\n        sx={{\n          borderRadius: '14px',\n          border: 1,\n          borderColor: 'divider',\n          bgcolor: 'background.paper',\n          boxShadow: '0 1px 2px rgba(15,23,42,.06)',\n          cursor: 'grab',\n          '&:hover': { borderColor: colorPalette[accent][400] },\n          '&:focus-within': { borderColor: colorPalette[accent][500] },\n        }}\n      >\n        <ButtonBase\n          onClick={() => !dragged.current && onOpen(task)}\n          aria-label={`${task.title}. ${person ? `Assigned to ${person.name}` : 'Unassigned'}. Open card ${task.id}`}\n          sx={{ display: 'block', width: '100%', textAlign: 'left', p: 1.5, pr: 5, borderRadius: '14px', '&:focus-visible': { outline: '2px solid', outlineColor: colorPalette[accent][500], outlineOffset: 2 } }}\n        >\n          {task.labels.length > 0 && (\n            <Stack direction=\"row\" sx={{ gap: 0.5, flexWrap: 'wrap', mb: 1 }}>\n              {task.labels.map((l) => (\n                <Chip key={l} size=\"xs\" variant=\"soft\" color={LABEL_COLOR[l]} label={l} />\n              ))}\n            </Stack>\n          )}\n          <Typography sx={{ fontSize: 14, fontWeight: 650, lineHeight: 1.35 }}>{task.title}</Typography>\n          <Stack direction=\"row\" sx={{ alignItems: 'center', gap: 1, mt: 1.25, flexWrap: 'wrap' }}>\n            <Typography component=\"span\" sx={{ fontSize: 12, color: 'text.secondary', fontWeight: 600 }}>\n              {task.id}\n            </Typography>\n            <DueChip due={task.due} done={task.column === 'done'} />\n            {task.checklist.length > 0 && (\n              <Box component=\"span\" aria-label={`Checklist ${done} of ${task.checklist.length}`} sx={{ display: 'inline-flex', alignItems: 'center', gap: 0.5, fontSize: 12, color: (t) => (done < task.checklist.length ? t.palette.text.secondary : colorPalette.success[t.palette.mode === 'dark' ? 300 : 700]) }}>\n                <CheckBoxOutlined sx={{ fontSize: 15 }} />\n                {done}/{task.checklist.length}\n              </Box>\n            )}\n            {task.description && <NotesOutlined aria-label=\"Has a description\" sx={{ fontSize: 15, color: 'text.secondary' }} />}\n            <Box sx={{ flex: 1 }} />\n            {person ? (\n              <Avatar size=\"xs\" variant=\"soft\" color={person.color} aria-label={person.name}>\n                {initials(person.name)}\n              </Avatar>\n            ) : (\n              <Typography component=\"span\" sx={{ fontSize: 12, color: 'text.secondary' }}>\n                Unassigned\n              </Typography>\n            )}\n          </Stack>\n        </ButtonBase>\n        <Stack data-no-drag sx={{ position: 'absolute', top: 4, right: 4, alignItems: 'center' }}>\n          <IconButton size=\"small\" aria-label={`Move ${task.id}`} aria-haspopup=\"menu\" aria-expanded={!!menu} onClick={(e) => setMenu(e.currentTarget)} sx={TAP}>\n            <MoreHoriz fontSize=\"small\" />\n          </IconButton>\n          <Box\n            aria-hidden\n            onPointerDown={(e: React.PointerEvent) => controls.start(e)}\n            sx={{ display: 'none', '@media (pointer: coarse)': { display: 'grid' }, placeItems: 'center', width: 36, height: 36, color: 'text.secondary', touchAction: 'none', cursor: 'grab' }}\n          >\n            <DragIndicator fontSize=\"small\" />\n          </Box>\n        </Stack>\n      </Box>\n      <Menu anchorEl={menu} open={!!menu} onClose={() => setMenu(null)} size=\"sm\" anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }} transformOrigin={{ vertical: 'top', horizontal: 'right' }}>\n        {COLUMNS.filter((c) => c.id !== task.column).map((c) => (\n          <MenuItem\n            key={c.id}\n            onClick={() => {\n              setMenu(null);\n              onMove(task, c.id);\n            }}\n          >\n            Move to {c.title}\n          </MenuItem>\n        ))}\n        <MenuItem\n          onClick={() => {\n            setMenu(null);\n            onOpen(task);\n          }}\n        >\n          Open card\n        </MenuItem>\n      </Menu>\n    </motion.li>\n  );\n}\n\nexport default function Kanban({ accent = 'success' }: { accent?: Accent }) {\n  const [tasks, setTasks] = React.useState<Task[]>(TASKS);\n  const [who, setWho] = React.useState<string | null>(null);\n  const [announce, setAnnounce] = React.useState('');\n  const [over, setOver] = React.useState<ColumnId | null>(null);\n  const [dragging, setDragging] = React.useState(false);\n  const [adding, setAdding] = React.useState<ColumnId | null>(null);\n  const [newTitle, setNewTitle] = React.useState('');\n  const [editing, setEditing] = React.useState<Task | null>(null);\n  const [dialogOpen, setDialogOpen] = React.useState(false);\n  const [newItem, setNewItem] = React.useState('');\n  const [toast, setToast] = React.useState<{ id: number; message: string; open: boolean } | null>(null);\n  const notify = (message: string) => setToast((t) => ({ id: (t?.id ?? 0) + 1, message, open: true }));\n  const columnEls = React.useRef<Partial<Record<ColumnId, HTMLElement | null>>>({});\n  const dialogTitle = React.useId();\n\n  const columnAt = (x: number, y: number) =>\n    COLUMNS.find((c) => {\n      const r = columnEls.current[c.id]?.getBoundingClientRect();\n      return r && x >= r.left && x <= r.right && y >= r.top && y <= r.bottom;\n    })?.id ?? null;\n\n  const move = (task: Task, to: ColumnId) => {\n    if (task.column === to) return;\n    setTasks((all) => [...all.filter((t) => t.id !== task.id), { ...task, column: to }]);\n    const col = COLUMNS.find((c) => c.id === to)!;\n    const count = tasks.filter((t) => t.column === to).length + 1;\n    const message = `${task.id} moved from ${columnTitle(task.column)} to ${col.title}.${col.limit && count > col.limit ? ` ${col.title} is over its limit of ${col.limit}.` : ''}`;\n    setAnnounce(message);\n    if (col.limit && count > col.limit) notify(`${col.title} is over its limit of ${col.limit}`);\n  };\n\n  const add = (column: ColumnId) => {\n    const title = newTitle.trim();\n    if (!title) return;\n    const id = `PL-${Math.max(...tasks.map((t) => Number(t.id.slice(3)))) + 1}`;\n    setTasks((all) => [...all, { id, column, title, description: '', assignee: who, labels: [], due: '', checklist: [] }]);\n    setNewTitle('');\n    setAnnounce(`${id} added to ${columnTitle(column)}.`);\n  };\n\n  const openCard = (t: Task) => {\n    setEditing({ ...t, checklist: t.checklist.map((c) => ({ ...c })) });\n    setNewItem('');\n    setDialogOpen(true);\n  };\n  const save = () => {\n    if (!editing || !editing.title.trim()) return;\n    setTasks((all) => all.map((t) => (t.id === editing.id ? { ...editing, title: editing.title.trim() } : t)));\n    setDialogOpen(false);\n    notify(`${editing.id} saved`);\n  };\n  const remove = () => {\n    if (!editing) return;\n    setTasks((all) => all.filter((t) => t.id !== editing.id));\n    setDialogOpen(false);\n    setAnnounce(`${editing.id} deleted.`);\n    notify(`${editing.id} deleted`);\n  };\n  const patch = (p: Partial<Task>) => setEditing((e) => (e ? { ...e, ...p } : e));\n\n  const shown = tasks.filter((t) => !who || t.assignee === who);\n  const total = tasks.length;\n  const doneCount = tasks.filter((t) => t.column === 'done').length;\n\n  return (\n    <MotionConfig reducedMotion=\"user\">\n      <Box sx={{ containerType: 'inline-size', height: '100%', minHeight: 560, display: 'flex', flexDirection: 'column', bgcolor: 'background.default', color: 'text.primary' }}>\n        {/* Header */}\n        <Box component=\"header\" sx={{ px: 2, pt: 2, pb: 1.5, borderBottom: 1, borderColor: 'divider', bgcolor: 'background.paper', [CQ.md]: { px: 3 } }}>\n          <Stack direction=\"row\" sx={{ alignItems: 'center', gap: 1.5, flexWrap: 'wrap' }}>\n            <Box aria-hidden sx={{ width: 32, height: 32, borderRadius: '10px', display: 'grid', placeItems: 'center', bgcolor: colorPalette[accent][600], flexShrink: 0 }}>\n              <svg width=\"18\" height=\"18\" viewBox=\"0 0 18 18\">\n                <path d=\"M9 16V8M9 8C9 5 6.5 3 3 3c0 3.5 2.5 5 6 5Zm0 0c0-3 2.5-5 6-5 0 3.5-2.5 5-6 5Z\" fill=\"none\" stroke=\"#fff\" strokeWidth=\"1.7\" strokeLinecap=\"round\" strokeLinejoin=\"round\" />\n              </svg>\n            </Box>\n            <Box sx={{ flex: 1, minWidth: 180 }}>\n              <Typography component=\"h2\" sx={{ fontWeight: 800, fontSize: 20, letterSpacing: '-0.02em', lineHeight: 1.2 }}>\n                Sprint 14 · Spring release\n              </Typography>\n              <Typography sx={{ fontSize: 13, color: 'text.secondary' }}>\n                Pollen app · {doneCount} of {total} cards done\n              </Typography>\n            </Box>\n            <Button\n              size=\"sm\"\n              color={accent}\n              startIcon={<Add />}\n              onClick={() => {\n                setAdding('todo');\n                setNewTitle('');\n              }}\n            >\n              New card\n            </Button>\n          </Stack>\n          <Stack direction=\"row\" role=\"group\" aria-label=\"Filter by person\" sx={{ alignItems: 'center', gap: 0.75, mt: 1.5, flexWrap: 'wrap' }}>\n            <Button size=\"sm\" variant={who === null ? 'soft' : 'ghost'} color={accent} aria-pressed={who === null} onClick={() => setWho(null)} sx={TAP}>\n              Everyone\n            </Button>\n            {PEOPLE.map((p) => {\n              const on = who === p.id;\n              return (\n                <Tooltip key={p.id} title={`${p.name}, ${p.role}`}>\n                  <ButtonBase\n                    aria-pressed={on}\n                    aria-label={`Only ${p.name}'s cards`}\n                    onClick={() => setWho(on ? null : p.id)}\n                    sx={{ borderRadius: '50%', p: '2px', border: 2, borderColor: on ? colorPalette[accent][500] : 'transparent', '&:focus-visible': { outline: '2px solid', outlineColor: colorPalette[accent][500], outlineOffset: 2 }, ...TAP }}\n                  >\n                    <Avatar size=\"sm\" variant={on ? 'solid' : 'soft'} color={p.color}>\n                      {initials(p.name)}\n                    </Avatar>\n                  </ButtonBase>\n                </Tooltip>\n              );\n            })}\n            {who && (\n              <Typography sx={{ fontSize: 13, color: 'text.secondary', ml: 0.5 }}>\n                {shown.length} {shown.length === 1 ? 'card' : 'cards'} for {personById(who)!.name}\n              </Typography>\n            )}\n          </Stack>\n        </Box>\n\n        {/* Board */}\n        <Box\n          role=\"region\"\n          aria-label=\"Board\"\n          sx={{\n            flex: 1,\n            minHeight: 0,\n            display: 'flex',\n            gap: 2,\n            p: 2,\n            overflowX: 'auto',\n            overflowY: 'auto',\n            scrollSnapType: 'x mandatory',\n            scrollPaddingInline: 16,\n            alignItems: 'flex-start',\n            [CQ.md]: { px: 3 },\n            [CQ.lg]: { display: 'grid', gridTemplateColumns: 'repeat(4, minmax(0, 1fr))', overflowX: 'visible' },\n          }}\n        >\n          {COLUMNS.map((c) => {\n            const mine = shown.filter((t) => t.column === c.id);\n            const all = tasks.filter((t) => t.column === c.id).length;\n            const overLimit = !!c.limit && all > c.limit;\n            const headingId = `kanban-col-${c.id}`;\n            return (\n              <Box\n                key={c.id}\n                ref={(el: HTMLElement | null) => {\n                  columnEls.current[c.id] = el;\n                }}\n                component=\"section\"\n                aria-labelledby={headingId}\n                data-testid={`kanban-column-${c.id}`}\n                sx={{\n                  flex: '0 0 min(280px, 82cqw)',\n                  scrollSnapAlign: 'start',\n                  minWidth: 0,\n                  borderRadius: '18px',\n                  p: 1.25,\n                  bgcolor: over === c.id && dragging ? colorPalette[accent].alpha20 : 'action.hover',\n                  outline: over === c.id && dragging ? `2px dashed ${colorPalette[accent][500]}` : 'none',\n                  transition: 'background-color .15s',\n                }}\n              >\n                <Stack direction=\"row\" sx={{ alignItems: 'center', gap: 1, px: 0.75, pt: 0.5, pb: 1.25 }}>\n                  <Box aria-hidden sx={{ width: 10, height: 10, borderRadius: '50%', bgcolor: colorPalette[c.color][500] }} />\n                  <Typography id={headingId} component=\"h3\" sx={{ fontWeight: 700, fontSize: 14, flex: 1 }}>\n                    {c.title}\n                  </Typography>\n                  <Chip\n                    size=\"xs\"\n                    variant=\"soft\"\n                    color={overLimit ? 'danger' : 'neutral'}\n                    label={c.limit ? `${all} / ${c.limit}` : all}\n                    aria-label={c.limit ? `${all} cards, limit ${c.limit}${overLimit ? ', over the limit' : ''}` : `${all} cards`}\n                  />\n                </Stack>\n                <Box component=\"ul\" aria-label={`${c.title} cards`} sx={{ m: 0, p: 0, display: 'grid', gap: 1 }}>\n                  {mine.map((t) => (\n                    <Card\n                      key={t.id}\n                      task={t}\n                      accent={accent}\n                      onOpen={openCard}\n                      onMove={move}\n                      onHover={(x, y) => setOver(columnAt(x, y))}\n                      onDragState={(d) => {\n                        setDragging(d);\n                        if (!d) setOver(null);\n                      }}\n                      onDrop={(task, x, y) => {\n                        const to = columnAt(x, y);\n                        if (to) move(task, to);\n                      }}\n                    />\n                  ))}\n                </Box>\n                {mine.length === 0 && (\n                  <Typography sx={{ fontSize: 13, color: 'text.secondary', textAlign: 'center', py: 2, border: 1, borderStyle: 'dashed', borderColor: 'divider', borderRadius: '12px' }}>\n                    {who ? 'No cards for this person' : 'Drop cards here'}\n                  </Typography>\n                )}\n                {adding === c.id ? (\n                  <Box component=\"form\" noValidate onSubmit={(e: React.FormEvent) => { e.preventDefault(); add(c.id); }} sx={{ mt: 1 }}>\n                    <TextField\n                      size=\"sm\"\n                      color={accent}\n                      fullWidth\n                      autoFocus\n                      placeholder=\"What needs doing?\"\n                      value={newTitle}\n                      onChange={(e) => setNewTitle(e.target.value)}\n                      onKeyDown={(e) => e.key === 'Escape' && setAdding(null)}\n                      slotProps={{ htmlInput: { 'aria-label': `New card title in ${c.title}` } }}\n                    />\n                    <Stack direction=\"row\" spacing={1} sx={{ mt: 1 }}>\n                      <Button size=\"sm\" type=\"submit\" color={accent} disabled={!newTitle.trim()}>\n                        Add card\n                      </Button>\n                      <IconButton size=\"small\" aria-label=\"Cancel adding a card\" onClick={() => setAdding(null)} sx={TAP}>\n                        <Close fontSize=\"small\" />\n                      </IconButton>\n                    </Stack>\n                  </Box>\n                ) : (\n                  <Button\n                    size=\"sm\"\n                    variant=\"ghost\"\n                    color=\"neutral\"\n                    startIcon={<Add />}\n                    fullWidth\n                    onClick={() => {\n                      setAdding(c.id);\n                      setNewTitle('');\n                    }}\n                    aria-label={`Add a card to ${c.title}`}\n                    sx={{ mt: 1, justifyContent: 'flex-start', ...TAP }}\n                  >\n                    Add a card\n                  </Button>\n                )}\n              </Box>\n            );\n          })}\n        </Box>\n\n        <Box role=\"status\" aria-live=\"polite\" sx={SR_ONLY}>\n          {announce}\n        </Box>\n\n        {/* Card dialog: edits a copy, Save writes it back. */}\n        <Dialog open={dialogOpen} onClose={() => setDialogOpen(false)} maxWidth=\"sm\" fullWidth aria-labelledby={dialogTitle} slotProps={{ transition: { onExited: () => setEditing(null) } }}>\n          {editing && (\n            <Box component=\"form\" noValidate sx={{ display: 'contents' }} onSubmit={(e: React.FormEvent) => { e.preventDefault(); save(); }}>\n              <DialogTitle id={dialogTitle} sx={{ pr: 7 }}>\n                {editing.id} · {columnTitle(editing.column)}\n                <IconButton aria-label=\"Close\" onClick={() => setDialogOpen(false)} sx={{ position: 'absolute', right: 12, top: 12, ...TAP }}>\n                  <Close />\n                </IconButton>\n              </DialogTitle>\n              <DialogContent>\n                <Stack spacing={2.25} sx={{ pt: 1 }}>\n                  <TextField label=\"Title\" color={accent} fullWidth value={editing.title} onChange={(e) => patch({ title: e.target.value })} error={!editing.title.trim()} helperText={!editing.title.trim() ? 'A card needs a title' : ' '} />\n                  <TextField label=\"Description\" color={accent} fullWidth multiline minRows={2} value={editing.description} onChange={(e) => patch({ description: e.target.value })} />\n                  <Box sx={{ display: 'grid', gap: 2, gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr' } }}>\n                    <Select label=\"Assignee\" color={accent} value={editing.assignee ?? ''} onChange={(e) => patch({ assignee: e.target.value || null })} displayEmpty SelectDisplayProps={{ 'aria-label': 'Assignee' }}>\n                      <MenuItem value=\"\">Unassigned</MenuItem>\n                      {PEOPLE.map((p) => (\n                        <MenuItem key={p.id} value={p.id}>\n                          {p.name}\n                        </MenuItem>\n                      ))}\n                    </Select>\n                    <TextField label=\"Due date\" type=\"date\" color={accent} fullWidth value={editing.due} onChange={(e) => patch({ due: e.target.value })} slotProps={{ inputLabel: { shrink: true } }} />\n                  </Box>\n                  <Box>\n                    <Typography id=\"kanban-labels\" sx={{ fontSize: 13, fontWeight: 700, mb: 1 }}>\n                      Labels\n                    </Typography>\n                    <Stack direction=\"row\" role=\"group\" aria-labelledby=\"kanban-labels\" sx={{ gap: 0.75, flexWrap: 'wrap' }}>\n                      {LABELS.map((l) => {\n                        const on = editing.labels.includes(l);\n                        return (\n                          <Chip\n                            key={l}\n                            size=\"sm\"\n                            variant={on ? 'soft' : 'outlined'}\n                            color={on ? LABEL_COLOR[l] : 'neutral'}\n                            label={l}\n                            clickable\n                            aria-pressed={on}\n                            onClick={() => patch({ labels: on ? editing.labels.filter((x) => x !== l) : [...editing.labels, l] })}\n                          />\n                        );\n                      })}\n                    </Stack>\n                  </Box>\n                  <Box>\n                    <Stack direction=\"row\" sx={{ alignItems: 'center', justifyContent: 'space-between', mb: 0.5 }}>\n                      <Typography sx={{ fontSize: 13, fontWeight: 700 }}>Checklist</Typography>\n                      <Typography sx={{ fontSize: 12, color: 'text.secondary' }}>\n                        {editing.checklist.filter((c) => c.done).length} of {editing.checklist.length}\n                      </Typography>\n                    </Stack>\n                    {editing.checklist.length > 0 && (\n                      <Progress size=\"sm\" color={accent} value={(editing.checklist.filter((c) => c.done).length / editing.checklist.length) * 100} aria-label=\"Checklist progress\" sx={{ mb: 1 }} />\n                    )}\n                    <Box sx={{ display: 'grid' }}>\n                      {editing.checklist.map((item) => (\n                        <Stack key={item.id} direction=\"row\" sx={{ alignItems: 'center' }}>\n                          <Checkbox\n                            size=\"sm\"\n                            color={accent}\n                            label={item.text}\n                            checked={item.done}\n                            onChange={(e) => patch({ checklist: editing.checklist.map((c) => (c.id === item.id ? { ...c, done: e.target.checked } : c)) })}\n                            sx={{ flex: 1, '& .MuiFormControlLabel-label': { textDecoration: item.done ? 'line-through' : 'none', color: item.done ? 'text.secondary' : 'text.primary' } }}\n                          />\n                          <IconButton size=\"small\" aria-label={`Remove \"${item.text}\"`} onClick={() => patch({ checklist: editing.checklist.filter((c) => c.id !== item.id) })} sx={TAP}>\n                            <Close fontSize=\"small\" />\n                          </IconButton>\n                        </Stack>\n                      ))}\n                    </Box>\n                    <Stack direction=\"row\" spacing={1} sx={{ mt: 1 }}>\n                      <TextField\n                        size=\"sm\"\n                        color={accent}\n                        fullWidth\n                        placeholder=\"Add an item\"\n                        value={newItem}\n                        onChange={(e) => setNewItem(e.target.value)}\n                        onKeyDown={(e) => {\n                          if (e.key === 'Enter' && newItem.trim()) {\n                            e.preventDefault();\n                            patch({ checklist: [...editing.checklist, { id: `c${Date.now()}`, text: newItem.trim(), done: false }] });\n                            setNewItem('');\n                          }\n                        }}\n                        slotProps={{ htmlInput: { 'aria-label': 'New checklist item' } }}\n                      />\n                      <Button\n                        size=\"sm\"\n                        variant=\"soft\"\n                        color={accent}\n                        disabled={!newItem.trim()}\n                        onClick={() => {\n                          patch({ checklist: [...editing.checklist, { id: `c${Date.now()}`, text: newItem.trim(), done: false }] });\n                          setNewItem('');\n                        }}\n                      >\n                        Add\n                      </Button>\n                    </Stack>\n                  </Box>\n                </Stack>\n              </DialogContent>\n              <DialogActions sx={{ justifyContent: 'space-between' }}>\n                <Button variant=\"ghost\" color=\"danger\" startIcon={<DeleteOutlined />} onClick={remove}>\n                  Delete\n                </Button>\n                <Stack direction=\"row\" spacing={1}>\n                  <Button variant=\"ghost\" color=\"neutral\" onClick={() => setDialogOpen(false)}>\n                    Cancel\n                  </Button>\n                  <Button type=\"submit\" color={accent} disabled={!editing.title.trim()}>\n                    Save\n                  </Button>\n                </Stack>\n              </DialogActions>\n            </Box>\n          )}\n        </Dialog>\n\n        <Snackbar\n          key={toast?.id ?? 0}\n          open={toast?.open ?? false}\n          autoHideDuration={3000}\n          onClose={(_, reason) => {\n            if (reason !== 'clickaway') setToast((t) => (t ? { ...t, open: false } : t));\n          }}\n          message={toast?.message ?? ''}\n          color=\"success\"\n          anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}\n        />\n      </Box>\n    </MotionConfig>\n  );\n}\n"},{"file":"data.ts","source":"// Sample board for \"Pollen\", a fictional team shipping a plant-care app.\n// Every person, card and date is made up.\n\nexport type Accent = 'primary' | 'secondary' | 'success' | 'warning' | 'danger' | 'info';\nexport type ColumnId = 'todo' | 'doing' | 'review' | 'done';\nexport type LabelId = 'Design' | 'iOS' | 'Android' | 'Backend' | 'Bug' | 'Research';\n\nexport type Person = { id: string; name: string; role: string; color: Accent };\nexport type CheckItem = { id: string; text: string; done: boolean };\nexport type Task = {\n  id: string;\n  column: ColumnId;\n  title: string;\n  description: string;\n  assignee: string | null;\n  labels: LabelId[];\n  /** ISO date (yyyy-mm-dd) or empty. */\n  due: string;\n  checklist: CheckItem[];\n};\n\nexport const COLUMNS: { id: ColumnId; title: string; limit?: number; color: Accent }[] = [\n  { id: 'todo', title: 'To do', color: 'info' },\n  { id: 'doing', title: 'In progress', limit: 3, color: 'warning' },\n  { id: 'review', title: 'Review', limit: 2, color: 'secondary' },\n  { id: 'done', title: 'Done', color: 'success' },\n];\n\nexport const LABEL_COLOR: Record<LabelId, Accent> = {\n  Design: 'secondary',\n  iOS: 'primary',\n  Android: 'success',\n  Backend: 'warning',\n  Bug: 'danger',\n  Research: 'info',\n};\n\nexport const PEOPLE: Person[] = [\n  { id: 'ab', name: 'Ada Brennan', role: 'Product design', color: 'secondary' },\n  { id: 'ko', name: 'Kofi Owusu', role: 'iOS', color: 'primary' },\n  { id: 'lm', name: 'Lucía Marín', role: 'Android', color: 'success' },\n  { id: 'rh', name: 'Rafael Holm', role: 'Backend', color: 'warning' },\n  { id: 'sn', name: 'Saanvi Nair', role: 'Research', color: 'info' },\n];\n\nexport const personById = (id: string | null) => PEOPLE.find((p) => p.id === id) ?? null;\nexport const initials = (name: string) => name.split(/\\s+/).slice(0, 2).map((p) => p[0]).join('').toUpperCase();\n\n/** \"Today\" in the sample, fixed so due-date badges never drift. */\nexport const TODAY = '2026-11-17';\nconst MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];\nexport const shortDate = (iso: string) => {\n  const [, m, d] = iso.split('-').map(Number);\n  return `${MONTHS[m - 1]} ${d}`;\n};\n/** Days from the sample's today; negative is overdue. */\nexport const daysLeft = (iso: string) => Math.round((Date.parse(iso) - Date.parse(TODAY)) / 86_400_000);\n\nlet n = 0;\nconst items = (...list: [string, boolean][]): CheckItem[] => list.map(([text, done]) => ({ id: `c${++n}`, text, done }));\n\nexport const TASKS: Task[] = [\n  {\n    id: 'PL-41',\n    column: 'todo',\n    title: 'Watering reminders: snooze options',\n    description: 'Let people snooze a reminder for an hour, until this evening or until tomorrow morning.',\n    assignee: 'ko',\n    labels: ['iOS'],\n    due: '2026-11-24',\n    checklist: items(['Agree on the three options', false], ['Notification actions', false], ['Settings screen copy', false]),\n  },\n  {\n    id: 'PL-42',\n    column: 'todo',\n    title: 'Interview five people who own 10+ plants',\n    description: 'Find out how they keep track of repotting and fertilizing today.',\n    assignee: 'sn',\n    labels: ['Research'],\n    due: '2026-11-21',\n    checklist: items(['Screener survey', true], ['Book sessions', false], ['Synthesis notes', false]),\n  },\n  {\n    id: 'PL-43',\n    column: 'todo',\n    title: 'Light meter crashes on older Android phones',\n    description: 'Crash when the camera permission is granted after the screen opens.',\n    assignee: 'lm',\n    labels: ['Android', 'Bug'],\n    due: '2026-11-19',\n    checklist: [],\n  },\n  {\n    id: 'PL-44',\n    column: 'todo',\n    title: 'Empty state for a new garden',\n    description: 'Illustration and two suggested first plants.',\n    assignee: null,\n    labels: ['Design'],\n    due: '',\n    checklist: [],\n  },\n  {\n    id: 'PL-37',\n    column: 'doing',\n    title: 'Plant detail screen redesign',\n    description: 'Bigger photo, care schedule as a timeline, and the light needs moved above the fold.',\n    assignee: 'ab',\n    labels: ['Design'],\n    due: '2026-11-18',\n    checklist: items(['Wireframes', true], ['Visual design', true], ['Dark theme pass', false], ['Hand-off notes', false]),\n  },\n  {\n    id: 'PL-38',\n    column: 'doing',\n    title: 'Sync schedules across devices',\n    description: 'Conflict rule: the most recent edit wins, per plant.',\n    assignee: 'rh',\n    labels: ['Backend'],\n    due: '2026-11-26',\n    checklist: items(['Schema change', true], ['Sync endpoint', false], ['Migration for old clients', false]),\n  },\n  {\n    id: 'PL-39',\n    column: 'doing',\n    title: 'Home screen widget',\n    description: 'Shows the next three plants that need water.',\n    assignee: 'ko',\n    labels: ['iOS'],\n    due: '2026-11-28',\n    checklist: items(['Small size', true], ['Medium size', false]),\n  },\n  {\n    id: 'PL-35',\n    column: 'review',\n    title: 'Photo upload retries on a bad connection',\n    description: 'Queue uploads and retry with backoff; show a small badge while pending.',\n    assignee: 'lm',\n    labels: ['Android'],\n    due: '2026-11-17',\n    checklist: items(['Queue', true], ['Backoff', true], ['Pending badge', true]),\n  },\n  {\n    id: 'PL-36',\n    column: 'review',\n    title: 'Care tips API pagination',\n    description: 'Cursor-based, 20 per page.',\n    assignee: 'rh',\n    labels: ['Backend'],\n    due: '2026-11-15',\n    checklist: items(['Cursor encoding', true], ['Docs', false]),\n  },\n  {\n    id: 'PL-31',\n    column: 'done',\n    title: 'Onboarding: pick your plants',\n    description: 'Search the catalog or scan a label.',\n    assignee: 'ab',\n    labels: ['Design', 'iOS'],\n    due: '2026-11-10',\n    checklist: items(['Search', true], ['Scan', true]),\n  },\n  {\n    id: 'PL-32',\n    column: 'done',\n    title: 'Usability test: reminder settings',\n    description: 'Six sessions. Main finding: people expect reminders per room, not only per plant.',\n    assignee: 'sn',\n    labels: ['Research'],\n    due: '2026-11-12',\n    checklist: [],\n  },\n];\n"}],
  "storefront": [{"file":"index.tsx","source":"'use client';\n// Storefront: \"Kiln & Co.\", a fictional ceramics shop. A product grid with filters\n// and sorting, a quick-view dialog, a cart drawer with a free-shipping meter and a\n// three-step checkout. Catalog in ./data.ts, product pictures drawn in ./art.tsx.\n// The page responds to the width of its container (container queries), so it works\n// full screen, in a panel or in a preview frame.\nimport * as React from 'react';\nimport { Box, Collapse, DialogActions, DialogContent, DialogTitle, Divider, FormControlLabel, IconButton, RadioGroup, Stack, Typography } from '@mui/material';\nimport ShoppingBagOutlined from '@mui/icons-material/ShoppingBagOutlined';\nimport Close from '@mui/icons-material/Close';\nimport Add from '@mui/icons-material/Add';\nimport Remove from '@mui/icons-material/Remove';\nimport TuneOutlined from '@mui/icons-material/TuneOutlined';\nimport LocalShippingOutlined from '@mui/icons-material/LocalShippingOutlined';\nimport CheckCircleOutlined from '@mui/icons-material/CheckCircleOutlined';\nimport DeleteOutlined from '@mui/icons-material/DeleteOutlined';\nimport VisibilityOutlined from '@mui/icons-material/VisibilityOutlined';\nimport { Alert, Badge, Button, Checkbox, Chip, Dialog, Drawer, MenuItem, Progress, Radio, Rating, Select, Slider, Snackbar, Stepper, TextField } from '@sorbet-ui/react';\nimport { colorPalette } from '@sorbet-ui/tokens';\nimport ProductArt, { glazeColor } from './art';\nimport { CATEGORIES, FREE_SHIPPING, PRODUCTS, SHIPPING, SORTS, money, type Accent, type Category, type Glaze, type Product, type ShippingId, type SortId } from './data';\n\nconst CQ = { sm: '@container (min-width: 600px)', md: '@container (min-width: 900px)' } as const;\nconst TAP = { '@media (pointer: coarse)': { minHeight: 44, minWidth: 44 } } as const;\nconst MAX_PRICE = 80;\n\ntype Line = { key: string; product: Product; glaze: Glaze; qty: number };\n\nfunction Qty({ value, onChange, label, min = 1, max = 10 }: { value: number; onChange: (n: number) => void; label: string; min?: number; max?: number }) {\n  return (\n    <Stack direction=\"row\" role=\"group\" aria-label={label} sx={{ alignItems: 'center', border: 1, borderColor: 'divider', borderRadius: 999, width: 'fit-content' }}>\n      <IconButton size=\"small\" aria-label=\"Decrease quantity\" disabled={value <= min} onClick={() => onChange(value - 1)} sx={TAP}>\n        <Remove fontSize=\"small\" />\n      </IconButton>\n      <Box component=\"output\" aria-live=\"polite\" sx={{ minWidth: 28, textAlign: 'center', fontWeight: 700, fontSize: 14, fontVariantNumeric: 'tabular-nums' }}>\n        {value}\n      </Box>\n      <IconButton size=\"small\" aria-label=\"Increase quantity\" disabled={value >= max} onClick={() => onChange(value + 1)} sx={TAP}>\n        <Add fontSize=\"small\" />\n      </IconButton>\n    </Stack>\n  );\n}\n\nfunction Swatches({ product, value, onChange, name }: { product: Product; value: Glaze; onChange: (g: Glaze) => void; name: string }) {\n  return (\n    <RadioGroup row aria-label=\"Glaze\" name={name} value={value.id} onChange={(e) => onChange(product.glazes.find((g) => g.id === e.target.value)!)} sx={{ gap: 1 }}>\n      {product.glazes.map((g) => {\n        const on = g.id === value.id;\n        return (\n          <Box\n            key={g.id}\n            component=\"label\"\n            title={g.name}\n            sx={{ position: 'relative', width: 34, height: 34, borderRadius: '50%', display: 'grid', placeItems: 'center', cursor: 'pointer', border: 2, borderColor: on ? 'text.primary' : 'transparent', '&:has(input:focus-visible)': { outline: '2px solid', outlineColor: 'text.primary', outlineOffset: 2 } }}\n          >\n            <Box component=\"input\" type=\"radio\" name={name} value={g.id} checked={on} onChange={() => onChange(g)} aria-label={g.name} sx={{ position: 'absolute', opacity: 0, inset: 0, m: 0, cursor: 'pointer' }} />\n            <Box aria-hidden sx={{ width: 24, height: 24, borderRadius: '50%', bgcolor: glazeColor(g), boxShadow: 'inset 0 0 0 1px rgba(15,23,42,.15)' }} />\n          </Box>\n        );\n      })}\n    </RadioGroup>\n  );\n}\n\nexport default function Storefront({ accent = 'danger' }: { accent?: Accent }) {\n  // Filters\n  const [cats, setCats] = React.useState<Category[]>([]);\n  const [maxPrice, setMaxPrice] = React.useState(MAX_PRICE);\n  const [inStock, setInStock] = React.useState(false);\n  const [sort, setSort] = React.useState<SortId>('featured');\n  const [filtersOpen, setFiltersOpen] = React.useState(false);\n  // Cart\n  const [cart, setCart] = React.useState<Line[]>([]);\n  const [cartOpen, setCartOpen] = React.useState(false);\n  // Quick view\n  const [viewOpen, setViewOpen] = React.useState(false);\n  const [viewing, setViewing] = React.useState<{ product: Product; glaze: Glaze; qty: number } | null>(null);\n  // Checkout\n  const [checkoutOpen, setCheckoutOpen] = React.useState(false);\n  const [step, setStep] = React.useState(0);\n  const [form, setForm] = React.useState({ name: '', email: '', address: '', city: '', postcode: '', card: '', expiry: '', cvc: '' });\n  const [touched, setTouched] = React.useState(false);\n  const [shipping, setShipping] = React.useState<ShippingId>('standard');\n  const [placed, setPlaced] = React.useState<{ id: string; total: number; email: string } | null>(null);\n  const [toast, setToast] = React.useState<{ id: number; message: string; open: boolean } | null>(null);\n  const notify = (message: string) => setToast((t) => ({ id: (t?.id ?? 0) + 1, message, open: true }));\n  const shopRef = React.useRef<HTMLElement>(null);\n  const viewTitle = React.useId();\n  const checkoutTitle = React.useId();\n\n  const products = React.useMemo(() => {\n    const list = PRODUCTS.filter((p) => (cats.length === 0 || cats.includes(p.category)) && p.price <= maxPrice && (!inStock || p.stock > 0));\n    if (sort === 'price-asc') return [...list].sort((a, b) => a.price - b.price);\n    if (sort === 'price-desc') return [...list].sort((a, b) => b.price - a.price);\n    if (sort === 'rating') return [...list].sort((a, b) => b.rating - a.rating);\n    return list;\n  }, [cats, maxPrice, inStock, sort]);\n  const filtered = cats.length > 0 || maxPrice < MAX_PRICE || inStock;\n  const clearFilters = () => {\n    setCats([]);\n    setMaxPrice(MAX_PRICE);\n    setInStock(false);\n  };\n\n  const count = cart.reduce((a, l) => a + l.qty, 0);\n  const subtotal = cart.reduce((a, l) => a + l.qty * l.product.price, 0);\n  const freeShip = subtotal >= FREE_SHIPPING;\n  const shipCost = cart.length === 0 ? 0 : shipping === 'standard' && freeShip ? 0 : SHIPPING[shipping].price;\n  const total = subtotal + shipCost;\n\n  const addToCart = (product: Product, glaze: Glaze, qty = 1) => {\n    const key = `${product.id}-${glaze.id}`;\n    setCart((c) => (c.some((l) => l.key === key) ? c.map((l) => (l.key === key ? { ...l, qty: Math.min(10, l.qty + qty) } : l)) : [...c, { key, product, glaze, qty }]));\n    notify(`${product.name} (${glaze.name}) added to your bag`);\n  };\n  const setQty = (key: string, qty: number) => setCart((c) => c.map((l) => (l.key === key ? { ...l, qty } : l)));\n\n  const quickView = (p: Product) => {\n    setViewing({ product: p, glaze: p.glazes[0], qty: 1 });\n    setViewOpen(true);\n  };\n\n  // Checkout validation\n  const errors = {\n    name: !form.name.trim() && 'Enter your name',\n    email: !/^\\S+@\\S+\\.\\S+$/.test(form.email) && 'Enter an email like you@example.com',\n    address: !form.address.trim() && 'Enter a street address',\n    city: !form.city.trim() && 'Enter a city',\n    postcode: !/^[A-Za-z0-9 -]{3,10}$/.test(form.postcode.trim()) && 'Enter a postal code',\n    card: form.card.replace(/\\s/g, '').length !== 16 && 'Card numbers have 16 digits',\n    expiry: !/^(0[1-9]|1[0-2])\\/\\d{2}$/.test(form.expiry) && 'Use MM/YY',\n    cvc: !/^\\d{3,4}$/.test(form.cvc) && '3 or 4 digits',\n  };\n  const stepFields: (keyof typeof errors)[][] = [['name', 'email', 'address', 'city', 'postcode'], ['card', 'expiry', 'cvc'], []];\n  const stepOk = stepFields[step].every((f) => !errors[f]);\n  const field = (key: keyof typeof form, label: string, extra: Partial<React.ComponentProps<typeof TextField>> = {}) => (\n    <TextField\n      label={label}\n      color={accent}\n      fullWidth\n      value={form[key]}\n      onChange={(e) => setForm((f) => ({ ...f, [key]: e.target.value }))}\n      error={touched && !!errors[key as keyof typeof errors]}\n      helperText={(touched && errors[key as keyof typeof errors]) || ' '}\n      {...extra}\n    />\n  );\n  const next = () => {\n    if (!stepOk) {\n      setTouched(true);\n      return;\n    }\n    setTouched(false);\n    if (step < 2) setStep(step + 1);\n    else {\n      setPlaced({ id: `KC-${1040 + cart.length * 7 + count}`, total, email: form.email });\n      setCart([]);\n    }\n  };\n  const startCheckout = () => {\n    setCartOpen(false);\n    setStep(0);\n    setTouched(false);\n    setPlaced(null);\n    setCheckoutOpen(true);\n  };\n\n  const filterPanel = (\n    <Stack spacing={2.5}>\n      <Box>\n        <Typography id=\"sf-cat\" sx={{ fontWeight: 700, fontSize: 14, mb: 0.5 }}>\n          Category\n        </Typography>\n        <Box role=\"group\" aria-labelledby=\"sf-cat\" sx={{ display: 'grid' }}>\n          {CATEGORIES.map((c) => (\n            <Checkbox\n              key={c}\n              size=\"sm\"\n              color={accent}\n              label={`${c} (${PRODUCTS.filter((p) => p.category === c).length})`}\n              checked={cats.includes(c)}\n              onChange={(e) => setCats((list) => (e.target.checked ? [...list, c] : list.filter((x) => x !== c)))}\n            />\n          ))}\n        </Box>\n      </Box>\n      <Box>\n        <Typography id=\"sf-price\" sx={{ fontWeight: 700, fontSize: 14, mb: 0.5 }}>\n          Max price: {money(maxPrice).replace('.00', '')}\n        </Typography>\n        <Box sx={{ px: 1 }}>\n          <Slider size=\"sm\" color={accent} min={20} max={MAX_PRICE} step={5} value={maxPrice} onChange={(_, v) => setMaxPrice(v as number)} aria-labelledby=\"sf-price\" getAriaValueText={(v) => `$${v}`} />\n        </Box>\n      </Box>\n      <Checkbox size=\"sm\" color={accent} label=\"In stock only\" checked={inStock} onChange={(e) => setInStock(e.target.checked)} />\n      {filtered && (\n        <Button size=\"sm\" variant=\"ghost\" color=\"neutral\" onClick={clearFilters} sx={{ alignSelf: 'flex-start' }}>\n          Clear filters\n        </Button>\n      )}\n    </Stack>\n  );\n\n  return (\n    <Box sx={{ containerType: 'inline-size', minHeight: '100%', bgcolor: 'background.default', color: 'text.primary' }}>\n      {/* Header */}\n      <Box component=\"header\" sx={{ position: 'sticky', top: 0, zIndex: 5, bgcolor: 'background.paper', borderBottom: 1, borderColor: 'divider' }}>\n        <Box sx={{ px: 2, py: 0.75, textAlign: 'center', fontSize: 13, fontWeight: 600, bgcolor: colorPalette[accent][700], color: '#fff' }}>Free shipping on orders over {money(FREE_SHIPPING).replace('.00', '')}</Box>\n        <Stack direction=\"row\" sx={{ alignItems: 'center', gap: 2, px: 2, minHeight: 60, maxWidth: 1200, mx: 'auto', [CQ.md]: { px: 4 } }}>\n          <Stack direction=\"row\" spacing={1} sx={{ alignItems: 'center', flex: 1 }}>\n            <Box aria-hidden sx={{ width: 28, height: 28 }}>\n              <ProductArt shape=\"vase\" glaze={{ id: 'logo', name: '', hue: accent }} size={28} />\n            </Box>\n            <Typography sx={{ fontWeight: 800, fontSize: 18, letterSpacing: '-0.02em' }}>Kiln &amp; Co.</Typography>\n          </Stack>\n          <Box component=\"nav\" aria-label=\"Shop\" sx={{ display: 'none', [CQ.sm]: { display: 'flex' }, gap: 0.5 }}>\n            {CATEGORIES.map((c) => (\n              <Button\n                key={c}\n                size=\"sm\"\n                variant={cats.length === 1 && cats[0] === c ? 'soft' : 'ghost'}\n                color={cats.length === 1 && cats[0] === c ? accent : 'neutral'}\n                onClick={() => {\n                  setCats([c]);\n                  shopRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });\n                }}\n              >\n                {c}\n              </Button>\n            ))}\n          </Box>\n          <IconButton aria-label={`Shopping bag, ${count} ${count === 1 ? 'item' : 'items'}`} onClick={() => setCartOpen(true)} sx={TAP}>\n            <Badge badgeContent={count} color={accent} invisible={count === 0}>\n              <ShoppingBagOutlined />\n            </Badge>\n          </IconButton>\n        </Stack>\n      </Box>\n\n      {/* Hero */}\n      <Box sx={{ maxWidth: 1200, mx: 'auto', px: 2, pt: 3, [CQ.md]: { px: 4, pt: 4 } }}>\n        <Box sx={{ position: 'relative', overflow: 'hidden', borderRadius: '24px', p: 3, display: 'grid', gap: 2, alignItems: 'center', bgcolor: (t) => (t.palette.mode === 'dark' ? colorPalette[accent].alpha12 : colorPalette[accent][50]), [CQ.sm]: { gridTemplateColumns: '1.2fr 1fr', p: 5 } }}>\n          <Box>\n            <Chip size=\"sm\" variant=\"soft\" color={accent} label=\"Winter collection\" />\n            <Typography component=\"h2\" sx={{ mt: 1.5, fontWeight: 800, fontSize: 30, lineHeight: 1.1, letterSpacing: '-0.03em', [CQ.md]: { fontSize: 44 } }}>\n              Made by hand for slow mornings\n            </Typography>\n            <Typography sx={{ mt: 1.5, color: 'text.secondary', maxWidth: 440 }}>Small-batch stoneware from a two-person studio. Every piece is thrown, trimmed and glazed by hand, so no two are quite the same.</Typography>\n            <Stack direction=\"row\" sx={{ gap: 1, mt: 2.5, flexWrap: 'wrap' }}>\n              <Button color={accent} onClick={() => shopRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' })}>\n                Shop the collection\n              </Button>\n              <Button\n                variant=\"outlined\"\n                color=\"neutral\"\n                onClick={() => {\n                  setCats([]);\n                  setSort('rating');\n                  shopRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });\n                }}\n              >\n                Best sellers\n              </Button>\n            </Stack>\n          </Box>\n          <Box aria-hidden sx={{ display: 'none', [CQ.sm]: { display: 'grid' }, gridTemplateColumns: '1fr 1fr', gap: 1 }}>\n            <ProductArt shape=\"vase\" glaze={PRODUCTS[6].glazes[0]} />\n            <Box sx={{ display: 'grid', gap: 1 }}>\n              <ProductArt shape=\"mug\" glaze={PRODUCTS[0].glazes[0]} />\n              <ProductArt shape=\"bowl\" glaze={PRODUCTS[2].glazes[0]} />\n            </Box>\n          </Box>\n        </Box>\n      </Box>\n\n      {/* Shop */}\n      <Box ref={shopRef} component=\"section\" aria-labelledby=\"sf-shop\" sx={{ maxWidth: 1200, mx: 'auto', px: 2, py: 4, scrollMarginTop: 100, [CQ.md]: { px: 4 } }}>\n        <Stack direction=\"row\" sx={{ alignItems: 'flex-end', justifyContent: 'space-between', gap: 2, flexWrap: 'wrap', mb: 2.5 }}>\n          <Box>\n            <Typography id=\"sf-shop\" component=\"h2\" sx={{ fontWeight: 800, fontSize: 24, letterSpacing: '-0.02em' }}>\n              {cats.length === 1 ? cats[0] : 'All pieces'}\n            </Typography>\n            <Typography role=\"status\" sx={{ fontSize: 14, color: 'text.secondary' }}>\n              {products.length} {products.length === 1 ? 'product' : 'products'}\n            </Typography>\n          </Box>\n          <Stack direction=\"row\" spacing={1} sx={{ alignItems: 'center' }}>\n            <Button size=\"sm\" variant=\"outlined\" color=\"neutral\" startIcon={<TuneOutlined />} aria-expanded={filtersOpen} aria-controls=\"sf-filters\" onClick={() => setFiltersOpen((o) => !o)} sx={{ [CQ.md]: { display: 'none' }, ...TAP }}>\n              Filters\n            </Button>\n            <Box sx={{ width: 190 }}>\n              <Select size=\"sm\" color={accent} value={sort} onChange={(e) => setSort(e.target.value as SortId)} SelectDisplayProps={{ 'aria-label': 'Sort by' }} fullWidth>\n                {SORTS.map((s) => (\n                  <MenuItem key={s.id} value={s.id}>\n                    {s.label}\n                  </MenuItem>\n                ))}\n              </Select>\n            </Box>\n          </Stack>\n        </Stack>\n\n        <Box sx={{ display: 'grid', gap: filtersOpen ? 3 : 0, gridTemplateColumns: 'minmax(0, 1fr)', [CQ.md]: { gap: 3, gridTemplateColumns: '220px minmax(0, 1fr)' } }}>\n          <Box component=\"aside\" aria-label=\"Filters\" id=\"sf-filters\">\n            <Box sx={{ display: 'none', [CQ.md]: { display: 'block', position: 'sticky', top: 110 } }}>{filterPanel}</Box>\n            <Box sx={{ [CQ.md]: { display: 'none' } }}>\n              <Collapse in={filtersOpen}>\n                <Box sx={{ p: 2, border: 1, borderColor: 'divider', borderRadius: '16px', bgcolor: 'background.paper' }}>{filterPanel}</Box>\n              </Collapse>\n            </Box>\n          </Box>\n\n          {products.length === 0 ? (\n            <Stack spacing={1} sx={{ alignItems: 'center', textAlign: 'center', py: 8, border: 1, borderStyle: 'dashed', borderColor: 'divider', borderRadius: '20px' }}>\n              <ShoppingBagOutlined sx={{ fontSize: 40, color: 'text.secondary' }} />\n              <Typography sx={{ fontWeight: 700 }}>Nothing matches those filters</Typography>\n              <Button size=\"sm\" variant=\"soft\" color={accent} onClick={clearFilters}>\n                Clear filters\n              </Button>\n            </Stack>\n          ) : (\n            <Box component=\"ul\" aria-label=\"Products\" sx={{ listStyle: 'none', m: 0, p: 0, display: 'grid', gap: 2, gridTemplateColumns: 'repeat(2, minmax(0, 1fr))', [CQ.sm]: { gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: 2.5 } }}>\n              {products.map((p) => {\n                const soldOut = p.stock === 0;\n                return (\n                  <Box component=\"li\" key={p.id} data-testid=\"product\" sx={{ minWidth: 0, display: 'flex', flexDirection: 'column' }}>\n                    <Box sx={{ position: 'relative', borderRadius: '18px', overflow: 'hidden', bgcolor: 'background.paper', border: 1, borderColor: 'divider', '&:hover .qv, &:focus-within .qv': { opacity: 1, transform: 'none' } }}>\n                      <ProductArt shape={p.shape} glaze={p.glazes[0]} />\n                      <Stack direction=\"row\" sx={{ position: 'absolute', top: 10, left: 10, gap: 0.5 }}>\n                        {p.isNew && <Chip size=\"xs\" variant=\"solid\" color={accent} label=\"New\" />}\n                        {soldOut ? <Chip size=\"xs\" variant=\"solid\" color=\"neutral\" label=\"Sold out\" /> : p.stock <= 5 && <Chip size=\"xs\" variant=\"soft\" color=\"warning\" label={`Only ${p.stock} left`} />}\n                      </Stack>\n                      <Button\n                        className=\"qv\"\n                        size=\"sm\"\n                        variant=\"solid\"\n                        color=\"neutral\"\n                        startIcon={<VisibilityOutlined />}\n                        onClick={() => quickView(p)}\n                        aria-label={`Quick view: ${p.name}`}\n                        sx={{ position: 'absolute', left: 10, right: 10, bottom: 10, opacity: 0, transform: 'translateY(6px)', transition: 'opacity .2s, transform .2s', '@media (hover: none)': { opacity: 1, transform: 'none' }, '@media (prefers-reduced-motion: reduce)': { transition: 'none' } }}\n                      >\n                        Quick view\n                      </Button>\n                    </Box>\n                    <Stack direction=\"row\" sx={{ alignItems: 'flex-start', gap: 1, mt: 1.25 }}>\n                      <Box sx={{ flex: 1, minWidth: 0 }}>\n                        <Typography component=\"h3\" sx={{ fontWeight: 700, fontSize: 15, lineHeight: 1.3 }}>\n                          {p.name}\n                        </Typography>\n                        <Stack direction=\"row\" sx={{ alignItems: 'center', gap: 0.5, mt: 0.25 }}>\n                          <Rating value={p.rating} precision={0.1} readOnly size=\"xs\" color=\"warning\" aria-label={`Rated ${p.rating} out of 5`} />\n                          <Typography sx={{ fontSize: 12, color: 'text.secondary' }}>({p.reviews})</Typography>\n                        </Stack>\n                      </Box>\n                      <Typography sx={{ fontWeight: 800, fontVariantNumeric: 'tabular-nums' }}>${p.price}</Typography>\n                    </Stack>\n                    <Stack direction=\"row\" sx={{ alignItems: 'center', justifyContent: 'space-between', mt: 1, gap: 1, flexWrap: 'wrap' }}>\n                      <Stack direction=\"row\" spacing={0.5} aria-label={`Glazes: ${p.glazes.map((g) => g.name).join(', ')}`} role=\"img\">\n                        {p.glazes.map((g) => (\n                          <Box key={g.id} sx={{ width: 14, height: 14, borderRadius: '50%', bgcolor: glazeColor(g), boxShadow: 'inset 0 0 0 1px rgba(15,23,42,.15)' }} />\n                        ))}\n                      </Stack>\n                      <Button size=\"sm\" variant=\"soft\" color={accent} disabled={soldOut} onClick={() => addToCart(p, p.glazes[0])} aria-label={soldOut ? `${p.name} is sold out` : `Add ${p.name} to bag`} sx={TAP}>\n                        {soldOut ? 'Sold out' : 'Add'}\n                      </Button>\n                    </Stack>\n                  </Box>\n                );\n              })}\n            </Box>\n          )}\n        </Box>\n      </Box>\n\n      {/* Footer */}\n      <Box component=\"footer\" sx={{ borderTop: 1, borderColor: 'divider', bgcolor: 'background.paper' }}>\n        <Box sx={{ maxWidth: 1200, mx: 'auto', px: 2, py: 4, display: 'grid', gap: 3, [CQ.sm]: { gridTemplateColumns: 'repeat(3, 1fr)' }, [CQ.md]: { px: 4 } }}>\n          {[\n            ['Handmade', 'Thrown and glazed in our studio. Small marks and variations are part of each piece.'],\n            ['Careful shipping', 'Packed in recycled paper pulp. Anything that arrives broken is replaced.'],\n            ['30-day returns', 'Changed your mind? Send it back unused within 30 days.'],\n          ].map(([t, d]) => (\n            <Box key={t}>\n              <Typography sx={{ fontWeight: 700, fontSize: 14 }}>{t}</Typography>\n              <Typography sx={{ fontSize: 13, color: 'text.secondary', mt: 0.5 }}>{d}</Typography>\n            </Box>\n          ))}\n        </Box>\n        <Typography sx={{ textAlign: 'center', fontSize: 12, color: 'text.secondary', pb: 3 }}>Kiln &amp; Co. is a sample store. Nothing here is for sale.</Typography>\n      </Box>\n\n      {/* Quick view */}\n      <Dialog open={viewOpen} onClose={() => setViewOpen(false)} maxWidth=\"md\" fullWidth aria-labelledby={viewTitle} slotProps={{ transition: { onExited: () => setViewing(null) } }}>\n        {viewing && (\n          <DialogContent sx={{ p: 0 }}>\n            <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr' } }}>\n              <Box sx={{ bgcolor: 'action.hover', p: 3, display: 'grid', placeItems: 'center' }}>\n                <Box sx={{ width: '100%', maxWidth: 340 }}>\n                  <ProductArt shape={viewing.product.shape} glaze={viewing.glaze} />\n                </Box>\n              </Box>\n              <Box sx={{ p: 3, position: 'relative' }}>\n                <IconButton aria-label=\"Close\" onClick={() => setViewOpen(false)} sx={{ position: 'absolute', top: 8, right: 8, ...TAP }}>\n                  <Close />\n                </IconButton>\n                <Typography sx={{ fontSize: 13, color: 'text.secondary', fontWeight: 600 }}>{viewing.product.category}</Typography>\n                <Typography id={viewTitle} component=\"h2\" sx={{ fontWeight: 800, fontSize: 26, letterSpacing: '-0.02em', pr: 5 }}>\n                  {viewing.product.name}\n                </Typography>\n                <Stack direction=\"row\" sx={{ alignItems: 'center', gap: 1, mt: 0.5 }}>\n                  <Rating value={viewing.product.rating} precision={0.1} readOnly size=\"sm\" color=\"warning\" aria-label={`Rated ${viewing.product.rating} out of 5`} />\n                  <Typography sx={{ fontSize: 13, color: 'text.secondary' }}>{viewing.product.reviews} reviews</Typography>\n                </Stack>\n                <Typography sx={{ fontWeight: 800, fontSize: 22, mt: 1.5 }}>${viewing.product.price}</Typography>\n                <Typography sx={{ color: 'text.secondary', mt: 1.5, fontSize: 15 }}>{viewing.product.blurb}</Typography>\n                <Typography sx={{ fontWeight: 700, fontSize: 14, mt: 2.5, mb: 1 }}>\n                  Glaze: <Box component=\"span\" sx={{ fontWeight: 500 }}>{viewing.glaze.name}</Box>\n                </Typography>\n                <Swatches product={viewing.product} value={viewing.glaze} onChange={(g) => setViewing((v) => (v ? { ...v, glaze: g } : v))} name=\"qv-glaze\" />\n                <Stack direction=\"row\" sx={{ alignItems: 'center', gap: 1.5, mt: 3, flexWrap: 'wrap' }}>\n                  <Qty label=\"Quantity\" value={viewing.qty} max={Math.max(1, Math.min(10, viewing.product.stock))} onChange={(q) => setViewing((v) => (v ? { ...v, qty: q } : v))} />\n                  <Button\n                    color={accent}\n                    disabled={viewing.product.stock === 0}\n                    startIcon={<ShoppingBagOutlined />}\n                    onClick={() => {\n                      addToCart(viewing.product, viewing.glaze, viewing.qty);\n                      setViewOpen(false);\n                    }}\n                    sx={{ flex: 1, minWidth: 160 }}\n                  >\n                    {viewing.product.stock === 0 ? 'Sold out' : `Add to bag · ${money(viewing.product.price * viewing.qty)}`}\n                  </Button>\n                </Stack>\n                <Typography sx={{ fontSize: 13, color: 'text.secondary', mt: 2, display: 'flex', alignItems: 'center', gap: 0.75 }}>\n                  <LocalShippingOutlined sx={{ fontSize: 18 }} />\n                  {viewing.product.stock > 0 ? `In stock, ships in 2 days` : 'Back in a few weeks'}\n                </Typography>\n              </Box>\n            </Box>\n          </DialogContent>\n        )}\n      </Dialog>\n\n      {/* Cart */}\n      <Drawer open={cartOpen} onClose={() => setCartOpen(false)} anchor=\"right\" aria-label=\"Shopping bag\">\n        <Box sx={{ width: 'min(400px, 92cqw)', display: 'flex', flexDirection: 'column', height: '100%' }}>\n          <Stack direction=\"row\" sx={{ alignItems: 'center', justifyContent: 'space-between', px: 2.5, py: 2 }}>\n            <Typography component=\"h2\" sx={{ fontWeight: 800, fontSize: 20 }}>\n              Your bag {count > 0 && `(${count})`}\n            </Typography>\n            <IconButton aria-label=\"Close bag\" onClick={() => setCartOpen(false)} sx={TAP}>\n              <Close />\n            </IconButton>\n          </Stack>\n          <Box sx={{ px: 2.5, pb: 2 }}>\n            <Typography sx={{ fontSize: 13, mb: 0.75 }}>{freeShip ? 'You get free standard shipping.' : `Add ${money(FREE_SHIPPING - subtotal)} more for free shipping.`}</Typography>\n            <Progress size=\"sm\" color={freeShip ? 'success' : accent} value={Math.min(100, (subtotal / FREE_SHIPPING) * 100)} aria-label=\"Progress to free shipping\" />\n          </Box>\n          <Divider />\n          <Box sx={{ flex: 1, overflowY: 'auto', px: 2.5 }}>\n            {cart.length === 0 ? (\n              <Stack spacing={1} sx={{ alignItems: 'center', textAlign: 'center', py: 6 }}>\n                <ShoppingBagOutlined sx={{ fontSize: 40, color: 'text.secondary' }} />\n                <Typography sx={{ fontWeight: 700 }}>Your bag is empty</Typography>\n                <Button size=\"sm\" variant=\"soft\" color={accent} onClick={() => setCartOpen(false)}>\n                  Keep shopping\n                </Button>\n              </Stack>\n            ) : (\n              <Box component=\"ul\" aria-label=\"Items in your bag\" sx={{ listStyle: 'none', m: 0, p: 0 }}>\n                {cart.map((l) => (\n                  <Box component=\"li\" key={l.key} sx={{ display: 'flex', gap: 1.5, py: 2, borderBottom: 1, borderColor: 'divider' }}>\n                    <Box sx={{ width: 72, flexShrink: 0, borderRadius: '12px', overflow: 'hidden', bgcolor: 'action.hover' }}>\n                      <ProductArt shape={l.product.shape} glaze={l.glaze} />\n                    </Box>\n                    <Box sx={{ flex: 1, minWidth: 0 }}>\n                      <Stack direction=\"row\" sx={{ justifyContent: 'space-between', gap: 1 }}>\n                        <Typography sx={{ fontWeight: 700, fontSize: 14 }}>{l.product.name}</Typography>\n                        <Typography sx={{ fontWeight: 700, fontSize: 14, fontVariantNumeric: 'tabular-nums' }}>{money(l.product.price * l.qty)}</Typography>\n                      </Stack>\n                      <Typography sx={{ fontSize: 13, color: 'text.secondary' }}>{l.glaze.name}</Typography>\n                      <Stack direction=\"row\" sx={{ alignItems: 'center', justifyContent: 'space-between', mt: 1 }}>\n                        <Qty label={`Quantity of ${l.product.name}`} value={l.qty} onChange={(q) => setQty(l.key, q)} />\n                        <IconButton aria-label={`Remove ${l.product.name}`} onClick={() => setCart((c) => c.filter((x) => x.key !== l.key))} sx={TAP}>\n                          <DeleteOutlined fontSize=\"small\" />\n                        </IconButton>\n                      </Stack>\n                    </Box>\n                  </Box>\n                ))}\n              </Box>\n            )}\n          </Box>\n          {cart.length > 0 && (\n            <Box sx={{ p: 2.5, borderTop: 1, borderColor: 'divider', bgcolor: 'background.paper' }}>\n              {[\n                ['Subtotal', money(subtotal)],\n                ['Shipping', freeShip ? 'Free' : `From ${money(SHIPPING.standard.price)}`],\n              ].map(([k, v]) => (\n                <Stack key={k} direction=\"row\" sx={{ justifyContent: 'space-between', fontSize: 14, mb: 0.75 }}>\n                  <span>{k}</span>\n                  <span>{v}</span>\n                </Stack>\n              ))}\n              <Button fullWidth size=\"lg\" color={accent} onClick={startCheckout} sx={{ mt: 1.5 }}>\n                Checkout · {money(subtotal + (freeShip ? 0 : SHIPPING.standard.price))}\n              </Button>\n            </Box>\n          )}\n        </Box>\n      </Drawer>\n\n      {/* Checkout */}\n      <Dialog open={checkoutOpen} onClose={() => setCheckoutOpen(false)} maxWidth=\"sm\" fullWidth aria-labelledby={checkoutTitle}>\n        <DialogTitle id={checkoutTitle} sx={{ pr: 7 }}>\n          {placed ? 'Order placed' : 'Checkout'}\n          <IconButton aria-label=\"Close checkout\" onClick={() => setCheckoutOpen(false)} sx={{ position: 'absolute', right: 12, top: 12, ...TAP }}>\n            <Close />\n          </IconButton>\n        </DialogTitle>\n        {placed ? (\n          <>\n            <DialogContent>\n              <Stack spacing={1.5} sx={{ alignItems: 'center', textAlign: 'center', py: 2 }}>\n                <CheckCircleOutlined sx={{ fontSize: 56, color: (t) => colorPalette.success[t.palette.mode === 'dark' ? 300 : 600] }} />\n                <Typography sx={{ fontWeight: 800, fontSize: 20 }}>Thank you, {form.name.split(' ')[0]}!</Typography>\n                <Typography color=\"text.secondary\">\n                  Order {placed.id} for {money(placed.total)} is confirmed. A receipt is on its way to {placed.email}.\n                </Typography>\n                <Alert color=\"info\" size=\"sm\">\n                  This is a sample store: nothing was charged and nothing will ship.\n                </Alert>\n              </Stack>\n            </DialogContent>\n            <DialogActions>\n              <Button color={accent} onClick={() => setCheckoutOpen(false)}>\n                Back to the shop\n              </Button>\n            </DialogActions>\n          </>\n        ) : (\n          <Box component=\"form\" noValidate sx={{ display: 'contents' }} onSubmit={(e: React.FormEvent) => { e.preventDefault(); next(); }}>\n            <DialogContent>\n              <Stepper activeStep={step} color={accent} size=\"sm\" alternativeLabel steps={[{ label: 'Shipping' }, { label: 'Payment' }, { label: 'Review' }]} sx={{ mb: 3 }} />\n              {step === 0 && (\n                <Box sx={{ display: 'grid', gap: 0.5, gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr' }, columnGap: 2 }}>\n                  {field('name', 'Full name', { autoComplete: 'name' })}\n                  {field('email', 'Email', { type: 'email', autoComplete: 'email' })}\n                  <Box sx={{ gridColumn: '1 / -1' }}>{field('address', 'Street address', { autoComplete: 'street-address' })}</Box>\n                  {field('city', 'City', { autoComplete: 'address-level2' })}\n                  {field('postcode', 'Postal code', { autoComplete: 'postal-code' })}\n                  <Box sx={{ gridColumn: '1 / -1' }}>\n                    <Typography id=\"sf-ship\" sx={{ fontWeight: 700, fontSize: 14, mb: 0.5 }}>\n                      Delivery\n                    </Typography>\n                    <RadioGroup aria-labelledby=\"sf-ship\" value={shipping} onChange={(e) => setShipping(e.target.value as ShippingId)}>\n                      {(Object.keys(SHIPPING) as ShippingId[]).map((id) => (\n                        <FormControlLabel\n                          key={id}\n                          value={id}\n                          control={<Radio color={accent} size=\"sm\" />}\n                          label={`${SHIPPING[id].label}, ${SHIPPING[id].detail} · ${id === 'standard' && freeShip ? 'Free' : money(SHIPPING[id].price)}`}\n                        />\n                      ))}\n                    </RadioGroup>\n                  </Box>\n                </Box>\n              )}\n              {step === 1 && (\n                <Box sx={{ display: 'grid', gap: 0.5, gridTemplateColumns: '1fr 1fr', columnGap: 2 }}>\n                  <Box sx={{ gridColumn: '1 / -1' }}>\n                    <Alert color=\"info\" size=\"sm\" sx={{ mb: 2 }}>\n                      Sample checkout: use any 16 digits, nothing is charged.\n                    </Alert>\n                    {field('card', 'Card number', { autoComplete: 'off', slotProps: { htmlInput: { inputMode: 'numeric', maxLength: 19 } } })}\n                  </Box>\n                  {field('expiry', 'Expiry (MM/YY)', { autoComplete: 'off', placeholder: '04/29' })}\n                  {field('cvc', 'Security code', { autoComplete: 'off', slotProps: { htmlInput: { inputMode: 'numeric', maxLength: 4 } } })}\n                </Box>\n              )}\n              {step === 2 && (\n                <Box>\n                  <Box component=\"ul\" aria-label=\"Order summary\" sx={{ listStyle: 'none', m: 0, p: 0 }}>\n                    {cart.map((l) => (\n                      <Box component=\"li\" key={l.key} sx={{ display: 'flex', justifyContent: 'space-between', gap: 2, py: 1, borderBottom: 1, borderColor: 'divider', fontSize: 14 }}>\n                        <span>\n                          {l.product.name}, {l.glaze.name} × {l.qty}\n                        </span>\n                        <span>{money(l.product.price * l.qty)}</span>\n                      </Box>\n                    ))}\n                  </Box>\n                  {[\n                    ['Subtotal', money(subtotal)],\n                    [`Shipping (${SHIPPING[shipping].label})`, shipCost === 0 ? 'Free' : money(shipCost)],\n                  ].map(([k, v]) => (\n                    <Stack key={k} direction=\"row\" sx={{ justifyContent: 'space-between', fontSize: 14, mt: 1 }}>\n                      <span>{k}</span>\n                      <span>{v}</span>\n                    </Stack>\n                  ))}\n                  <Stack direction=\"row\" sx={{ justifyContent: 'space-between', mt: 1.5, fontWeight: 800, fontSize: 18 }}>\n                    <span>Total</span>\n                    <span>{money(total)}</span>\n                  </Stack>\n                  <Typography sx={{ fontSize: 13, color: 'text.secondary', mt: 2 }}>\n                    Ships to {form.name}, {form.address}, {form.city} {form.postcode}. Card ending {form.card.replace(/\\s/g, '').slice(-4)}.\n                  </Typography>\n                </Box>\n              )}\n            </DialogContent>\n            <DialogActions sx={{ justifyContent: 'space-between' }}>\n              <Button variant=\"ghost\" color=\"neutral\" onClick={() => (step === 0 ? setCheckoutOpen(false) : setStep(step - 1))}>\n                {step === 0 ? 'Cancel' : 'Back'}\n              </Button>\n              <Button type=\"submit\" color={accent} disabled={cart.length === 0}>\n                {step === 2 ? `Place order · ${money(total)}` : 'Continue'}\n              </Button>\n            </DialogActions>\n          </Box>\n        )}\n      </Dialog>\n\n      <Snackbar\n        key={toast?.id ?? 0}\n        open={toast?.open ?? false}\n        autoHideDuration={2500}\n        onClose={(_, reason) => {\n          if (reason !== 'clickaway') setToast((t) => (t ? { ...t, open: false } : t));\n        }}\n        message={toast?.message ?? ''}\n        color=\"success\"\n        action={\n          <Button size=\"sm\" variant=\"plain\" color=\"neutral\" onClick={() => setCartOpen(true)} sx={{ color: 'inherit' }}>\n            View bag\n          </Button>\n        }\n        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}\n      />\n    </Box>\n  );\n}\n"},{"file":"art.tsx","source":"// Product pictures drawn in SVG from a shape and a glaze: no image files to host,\n// sharp at any size, and every color is a design token. Decorative: the product\n// name is always next to the picture, so the SVG is aria-hidden.\nimport { colorPalette } from '@sorbet-ui/tokens';\nimport type { Glaze, Shape } from './data';\n\nconst BODY: Record<Shape, string> = {\n  mug: 'M58 70h74v62c0 14-11 24-24 24H82c-13 0-24-10-24-24V70Z',\n  cup: 'M64 84h72l-6 56c-1 10-9 16-19 16H89c-10 0-18-6-19-16l-6-56Z',\n  bowl: 'M34 96h132c0 34-28 58-66 58S34 130 34 96Z',\n  'deep-bowl': 'M42 78h116c0 46-24 78-58 78S42 124 42 78Z',\n  plate: 'M24 118c0-14 34-24 76-24s76 10 76 24-34 26-76 26-76-12-76-26Z',\n  vase: 'M86 36h28v14c0 8 18 22 18 52 0 34-14 54-32 54s-32-20-32-54c0-30 18-44 18-52V36Z',\n  'bud-vase': 'M92 74h16v10c14 6 24 20 24 38 0 20-14 34-32 34s-32-14-32-34c0-18 10-32 24-38V74Z',\n};\n\n/** Glaze swatch color (the 400 shade reads as a glaze in light and dark). */\nexport const glazeColor = (g: Glaze) => colorPalette[g.hue][g.hue === 'neutral' ? 200 : 400];\n\nexport default function ProductArt({ shape, glaze, size = '100%' }: { shape: Shape; glaze: Glaze; size?: number | string }) {\n  const scale = colorPalette[glaze.hue];\n  const fill = glazeColor(glaze);\n  return (\n    <svg viewBox=\"0 0 200 180\" width={size} height={size} aria-hidden=\"true\" style={{ display: 'block' }}>\n      {/* Backdrop: a soft blob in the glaze's lightest shade. */}\n      <path d=\"M30 60c10-34 60-50 100-40s62 46 52 86-58 64-100 56S20 94 30 60Z\" fill={scale[100]} />\n      <ellipse cx=\"100\" cy=\"160\" rx=\"62\" ry=\"7\" fill={scale[200]} opacity=\".7\" />\n      {shape === 'mug' && <path d=\"M132 86c18 0 26 8 26 20s-8 20-26 20\" fill=\"none\" stroke={scale[500]} strokeWidth=\"9\" strokeLinecap=\"round\" />}\n      <path d={BODY[shape]} fill={fill} />\n      {/* Raw clay at the foot and a highlight. */}\n      {shape !== 'plate' && <path d=\"M70 152h60\" stroke={colorPalette.warning[200]} strokeWidth=\"6\" strokeLinecap=\"round\" />}\n      {shape === 'plate' ? (\n        <ellipse cx=\"100\" cy=\"116\" rx=\"50\" ry=\"13\" fill={scale[200]} opacity=\".75\" />\n      ) : (\n        <path d={shape.includes('vase') ? 'M90 98c-4 14-4 30 2 42' : 'M72 104c0 12 4 24 12 32'} fill=\"none\" stroke=\"#fff\" strokeOpacity=\".55\" strokeWidth=\"6\" strokeLinecap=\"round\" />\n      )}\n      {(shape === 'bowl' || shape === 'deep-bowl') && <ellipse cx=\"100\" cy={shape === 'bowl' ? 96 : 78} rx={shape === 'bowl' ? 66 : 58} ry=\"9\" fill={scale[600]} />}\n    </svg>\n  );\n}\n"},{"file":"data.ts","source":"// Sample catalog for \"Kiln & Co.\", a fictional ceramics studio. Products, prices and\n// reviews are made up. Product pictures are drawn in ./art.tsx from `shape` + `glaze`.\n\nexport type Accent = 'primary' | 'secondary' | 'success' | 'warning' | 'danger' | 'info';\nexport type Category = 'Mugs' | 'Bowls' | 'Plates' | 'Vases';\nexport type Shape = 'mug' | 'cup' | 'bowl' | 'deep-bowl' | 'plate' | 'vase' | 'bud-vase';\n/** Glazes map to token hues, so every swatch is a design-system color. */\nexport type Glaze = { id: string; name: string; hue: Accent | 'neutral' };\n\nexport type Product = {\n  id: string;\n  name: string;\n  category: Category;\n  shape: Shape;\n  price: number;\n  rating: number;\n  reviews: number;\n  stock: number;\n  glazes: Glaze[];\n  blurb: string;\n  isNew?: boolean;\n};\n\nexport const CATEGORIES: Category[] = ['Mugs', 'Bowls', 'Plates', 'Vases'];\n\nconst G = {\n  sea: { id: 'sea', name: 'Sea glass', hue: 'info' },\n  sky: { id: 'sky', name: 'Morning sky', hue: 'primary' },\n  moss: { id: 'moss', name: 'Moss', hue: 'success' },\n  honey: { id: 'honey', name: 'Honey', hue: 'warning' },\n  clay: { id: 'clay', name: 'Red clay', hue: 'danger' },\n  plum: { id: 'plum', name: 'Plum', hue: 'secondary' },\n  chalk: { id: 'chalk', name: 'Chalk', hue: 'neutral' },\n} satisfies Record<string, Glaze>;\n\nexport const PRODUCTS: Product[] = [\n  { id: 'p1', name: 'Morning mug', category: 'Mugs', shape: 'mug', price: 28, rating: 4.8, reviews: 214, stock: 18, glazes: [G.sky, G.honey, G.chalk], blurb: 'A 12 oz mug with a thumb rest on the handle. Holds heat well and fits under most espresso machines.' },\n  { id: 'p2', name: 'Pour-over cup', category: 'Mugs', shape: 'cup', price: 22, rating: 4.6, reviews: 98, stock: 4, glazes: [G.moss, G.chalk], blurb: 'A handle-less 8 oz cup, unglazed at the foot so it sits warm in the hand.' },\n  { id: 'p3', name: 'Everyday bowl', category: 'Bowls', shape: 'bowl', price: 34, rating: 4.9, reviews: 302, stock: 25, glazes: [G.sea, G.clay, G.chalk], blurb: 'Wide and shallow, for salads, noodles and anything with a sauce.', isNew: true },\n  { id: 'p4', name: 'Ramen bowl', category: 'Bowls', shape: 'deep-bowl', price: 46, rating: 4.7, reviews: 76, stock: 0, glazes: [G.plum, G.sea], blurb: 'Deep enough for a full bowl of broth, with a rim that keeps chopsticks from rolling off.' },\n  { id: 'p5', name: 'Side plate', category: 'Plates', shape: 'plate', price: 24, rating: 4.5, reviews: 121, stock: 40, glazes: [G.honey, G.moss, G.sky], blurb: 'An 8 inch plate for toast, cake or small plates. Stacks flat.' },\n  { id: 'p6', name: 'Dinner plate', category: 'Plates', shape: 'plate', price: 38, rating: 4.8, reviews: 189, stock: 12, glazes: [G.chalk, G.sea], blurb: 'A 10.5 inch plate with a low rim. Oven, microwave and dishwasher safe.' },\n  { id: 'p7', name: 'Tall vase', category: 'Vases', shape: 'vase', price: 64, rating: 4.9, reviews: 54, stock: 6, glazes: [G.clay, G.plum, G.honey], blurb: 'Thrown in one piece, 11 inches tall. Watertight, with a narrow neck for a few long stems.', isNew: true },\n  { id: 'p8', name: 'Bud vase', category: 'Vases', shape: 'bud-vase', price: 26, rating: 4.4, reviews: 67, stock: 30, glazes: [G.sky, G.moss, G.clay], blurb: 'Small enough for a windowsill. Looks best in threes.' },\n  { id: 'p9', name: 'Latte mug', category: 'Mugs', shape: 'mug', price: 32, rating: 4.7, reviews: 143, stock: 9, glazes: [G.plum, G.sea], blurb: 'A wider 14 oz mug for milky coffee and soup on cold days.', isNew: true },\n  { id: 'p10', name: 'Serving bowl', category: 'Bowls', shape: 'deep-bowl', price: 72, rating: 4.6, reviews: 38, stock: 3, glazes: [G.honey, G.chalk], blurb: 'Big enough for a salad for six. Each one is signed on the base.' },\n];\n\nexport const SORTS = [\n  { id: 'featured', label: 'Featured' },\n  { id: 'price-asc', label: 'Price: low to high' },\n  { id: 'price-desc', label: 'Price: high to low' },\n  { id: 'rating', label: 'Top rated' },\n] as const;\nexport type SortId = (typeof SORTS)[number]['id'];\n\nexport const FREE_SHIPPING = 75;\nexport const SHIPPING = { standard: { label: 'Standard', detail: '3 to 5 business days', price: 6 }, express: { label: 'Express', detail: 'Next business day', price: 14 } } as const;\nexport type ShippingId = keyof typeof SHIPPING;\n\nexport const money = (n: number) => `$${n.toFixed(2)}`;\n"}],
};
